    "explanation": "**[핵심 개념]**\n\n지수법칙 중 같은 밑의 거듭제곱을 나눌 때 적용되는 법칙입니다.\n- 같은 밑 $a$에 대해 $\\dfrac{a^m}{a^n} = a^{m-n}$\n\n이 법칙은 거듭제곱의 나눗셈을 지수의 뺄셈으로 간단히 계산할 수 있게 해줍니다.\n\n**[풀이]**\n\n주어진 식: $\\dfrac{2^{7}}{2^{3}}=2^k$\n\n지수법칙을 적용하면:\n$$\\dfrac{2^{7}}{2^{3}} = 2^{7-3} = 2^4$$\n\n따라서:\n$$2^4 = 2^k$$\n\n양변의 밑이 같으므로 지수끼리 같아야 합니다:\n$$k = 4$$\n\n**[정답 확인]**\n\n지수법칙 $\\dfrac{a^m}{a^n} = a^{m-n}$을 올바르게 적용하여 $7-3=4$를 구했으므로 $k=4$가 정답입니다.\n\n**[오답 분석]**\n\n- ① $8$: $7+3=10$이 아닌 $7-3$을 계산해야 합니다. 나눗셈인데 지수를 더하는 실수입니다.\n- ③ $9$: 계산 오류로 보이며, 지수법칙을 잘못 적용한 경우입니다.\n- ④ $7$: 분자의 지수만 선택한 오류입니다. 나눗셈을 무시하고 답을 선택했습니다.\n- ⑤ $11$: $7+3=10$이 아닙니다. 더하기를 하더라도 틀린 계산입니다.\n\n**[핵심 포인트]**\n\n$\\dfrac{a^m}{a^n} = a^{m-n}$ (같은 밑의 거듭제곱 나눗셈은 지수를 **뺍니다**)\n거듭제곱의 곱셈 $a^m \\times a^n = a^{m+n}$과 혼동하지 않도록 주의하세요.",
