    "explanation": "**[핵심 개념]**\n지수법칙 중 같은 밑을 가진 거듭제곱의 나눗셈 공식입니다.\n- $a^m \\div a^n = a^{m-n}$ (단, $a \\neq 0$)\n- 같은 밑의 거듭제곱을 나눌 때는 지수를 뺍니다.\n\n**[풀이]**\n\n주어진 식: $\\dfrac{3^{7}}{3^{2}}=3^k$\n\n지수법칙을 적용합니다.\n\n$$\\dfrac{3^{7}}{3^{2}} = 3^{7-2}$$\n\n지수를 계산합니다.\n\n$$3^{7-2} = 3^{5}$$\n\n따라서 $3^k = 3^5$이므로\n\n$$k = 5$$\n\n**[정답 확인]**\n지수법칙 $\\dfrac{a^m}{a^n} = a^{m-n}$을 올바르게 적용하여 $7-2=5$를 얻었으므로 정답은 ①번입니다.\n\n**[오답 분석]**\n- **②번 (15)**: $7 \\times 2 = 14$로 잘못 계산하거나, 지수를 곱한 경우\n- **③번 (8)**: $7+2=9$로 덧셈을 한 경우 (나눗셈인데 덧셈 사용)\n- **④번 (6)**: $7-1=6$으로 잘못 계산한 경우\n- **⑤번 (9)**: $7+2=9$로 덧셈을 한 경우\n\n**[핵심 포인트]**\n같은 밑의 거듭제곱 나눗셈은 **지수를 빼는 것**이 핵심입니다. 덧셈이나 곱셈과 혼동하지 않도록 주의하세요.",
