    "explanation": "**[핵심 개념]**\n로그의 정의와 성질을 이용한 문제입니다.\n- 로그의 기본 성질: $\\log_a(a^x) = x$ (단, $a > 0, a \\neq 1$)\n- 이는 \"밑 $a$를 몇 제곱하면 $a^x$가 되는가?\"라는 질문에 답하는 것입니다.\n\n**[풀이]**\n\n주어진 식을 두 부분으로 나누어 계산합니다.\n\n**첫 번째 항: $\\log_3(3^4)$**\n\n로그의 성질 $\\log_a(a^x) = x$를 적용하면:\n$$\\log_3(3^4) = 4$$\n\n(이유: 3을 몇 제곱하면 $3^4$가 되는가? → 4제곱하면 된다)\n\n**두 번째 항: $\\log_2(2^2)$**\n\n마찬가지로 로그의 성질을 적용하면:\n$$\\log_2(2^2) = 2$$\n\n(이유: 2를 몇 제곱하면 $2^2$가 되는가? → 2제곱하면 된다)\n\n**전체 계산:**\n$$\\log_3(3^4) + \\log_2(2^2) = 4 + 2 = 6$$\n\n**[정답 확인]**\n$4 + 2 = 6$이므로 정답은 **⑤번**입니다.\n\n**[오답 분석]**\n- **① 2**: $\\log_2(2^2) = 2$만 계산한 경우\n- **② 0**: 두 항을 뺀 경우 ($4 - 2 = 2$도 아니므로 계산 실수)\n- **③ 8**: $\\log_3(3^4) = 4$를 $3 × 4 = 12$ 등으로 잘못 계산한 경우\n- **④ 9**: 지수를 더한 경우 ($4 + 2 + 3 = 9$ 등 근거 없는 계산)\n\n**[핵심 포인트]**\n$\\log_a(a^x) = x$는 로그 계산의 가장 기본이 되는 공식입니다. 밑과 진수의 밑이 같으면 지수만 추출하면 된다는 점을 항상 기억하세요.",
