    "answer": 3,
    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위해서는 먼저 지수 부분을 분리해야 합니다. $a^{f(x)} = b$ 형태의 방정식에서 양변에 같은 밑의 거듭제곱으로 만들거나, 양변에 로그를 취하는 방법을 사용합니다. 이 문제는 지수식을 한쪽으로 분리한 후 밑이 같도록 변형하는 방식으로 풀 수 있습니다.\n\n**[풀이]**\n\n주어진 방정식: $2^{x-3}+1=5$\n\n**Step 1: 지수항 분리**\n$$2^{x-3}+1=5$$\n$$2^{x-3}=5-1$$\n$$2^{x-3}=4$$\n\n**Step 2: 우변을 같은 밑으로 표현**\n우변의 4를 2의 거듭제곱으로 나타내면:\n$$4 = 2^2$$\n\n따라서:\n$$2^{x-3}=2^2$$\n\n**Step 3: 지수 비교**\n두 거듭제곱의 밑이 같으므로 지수끼리 같아야 합니다:\n$$x-3=2$$\n\n**Step 4: x 구하기**\n$$x=2+3$$\n$$x=5$$\n\n**[정답 확인]**\n$x=5$를 원래 방정식에 대입하면: $2^{5-3}+1=2^2+1=4+1=5$ ✓\n\n**[오답 분석]**\n- **① 선지 2**: $2^{2-3}+1=2^{-1}+1=0.5+1=1.5 \\neq 5$ (지수 계산 오류)\n- **② 선지 7**: $2^{7-3}+1=2^4+1=16+1=17 \\neq 5$ (지수 비교 실수)\n- **③ 선지 8**: $2^{8-3}+1=2^5+1=32+1=33 \\neq 5$ (부호 혼동)\n- **⑤ 선지 4**: $2^{4-3}+1=2^1+1=2+1=3 \\neq 5$ (지수 계산 오류)\n\n**[핵심 포인트]**\n- 지수방정식에서는 먼저 지수 항을 분리한 후, 양변의 밑을 같게 만들어 지수끼리 같다는 조건을 이용합니다.\n- $a^m = a^n$ (단, $a>0, a \\neq 1$)이면 $m=n$입니다.",
