    "explanation": "**[핵심 개념]**\n지수방정식을 푸는 기본 원리는 지수의 밑을 같게 만든 후, 지수끼리 같다는 성질을 이용하는 것입니다. 즉, $a^m = a^n$이면 $m = n$입니다. 이 문제에서는 지수식을 먼저 정리하여 $3^f(x) = 3^n$ 형태로 만들어야 합니다.\n\n**[풀이]**\n\n주어진 방정식: $3^{x-2}+2=11$\n\n**Step 1: 지수항을 분리하기**\n\n양변에서 2를 빼면:\n$$3^{x-2} = 11 - 2$$\n$$3^{x-2} = 9$$\n\n**Step 2: 우변을 3의 거듭제곱으로 표현**\n\n$9 = 3^2$이므로:\n$$3^{x-2} = 3^2$$\n\n**Step 3: 지수끼리 같다고 놓기**\n\n밑이 같으므로 지수가 같아야 합니다:\n$$x - 2 = 2$$\n\n**Step 4: x 구하기**\n\n$$x = 2 + 2 = 4$$\n\n**[정답 확인]**\n\n$x=4$를 원래 식에 대입하면: $3^{4-2}+2 = 3^2+2 = 9+2 = 11$ ✓\n\n**[오답 분석]**\n\n- ① $x=5$: $3^{5-2}+2 = 3^3+2 = 27+2 = 29 \\neq 11$\n- ② $x=9$: $3^{9-2}+2 = 3^7+2 = 2187+2 = 2189 \\neq 11$\n- ④ $x=10$: $3^{10-2}+2 = 3^8+2 = 6561+2 = 6563 \\neq 11$\n- ⑤ $x=7$: $3^{7-2}+2 = 3^5+2 = 243+2 = 245 \\neq 11$\n\n**[핵심 포인트]**\n\n지수방정식을 풀 때는 (1) 먼저 지수항만 분리하고, (2) 우변을 밑과 같은 거듭제곱으로 표현한 후, (3) 지수끼리 같다고 놓아야 합니다. 항상 구한 답을 원래 식에 대입하여 검증하는 습관을 들이세요.",
