    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위한 기본 원리는 양변을 같은 밑의 거듭제곱 형태로 만드는 것입니다. \n- 지수방정식 $a^f(x) = a^{g(x)}$에서 $a > 0, a \\neq 1$이면 $f(x) = g(x)$\n- 또한 $2^m = n$ 형태일 때, 로그를 이용하여 $m = \\log_2 n$으로 풀 수 있습니다.\n\n**[풀이]**\n\n주어진 방정식: $2^{x-4}+3=7$\n\n**Step 1:** 지수항을 분리합니다.\n$$2^{x-4}+3=7$$\n$$2^{x-4}=7-3$$\n$$2^{x-4}=4$$\n\n**Step 2:** 우변을 2의 거듭제곱으로 나타냅니다.\n$$4 = 2^2$$\n\n따라서:\n$$2^{x-4}=2^2$$\n\n**Step 3:** 지수방정식의 성질을 적용합니다.\n$$a^m = a^n \\text{ (단, } a > 0, a \\neq 1\\text{)이면 } m = n$$\n\n밑이 같으므로:\n$$x-4=2$$\n\n**Step 4:** $x$를 구합니다.\n$$x=2+4$$\n$$x=6$$\n\n**[정답 확인]**\n$x=6$을 원래 방정식에 대입하면: $2^{6-4}+3=2^2+3=4+3=7$ ✓\n\n**[오답 분석]**\n- **① 13:** $2^{x-4}=4$에서 지수만 더한 경우 ($x-4=4$로 잘못 계산)\n- **② 7:** 7을 그대로 선택한 경우 (방정식의 우변값을 $x$로 착각)\n- **③ 2:** $x-4=2$에서 $x=2$로만 답한 경우 (뺄셈을 덧셈으로 하지 않음)\n- **④ 8:** 계산 실수로 $x-4=4$라 한 경우 ($2^{x-4}=4$를 $2^{x-4}=16$으로 잘못 계산)\n\n**[핵심 포인트]**\n지수방정식을 풀 때는 ① 상수항을 먼저 이동시켜 지수항을 분리하고, ② 양변을 같은 밑의 거듭제곱으로 만들어 지수끼리 같다고 놓는 순서를 반드시 지켜야 합니다.",
