    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위해서는 같은 밑을 가진 거듭제곱으로 만들어야 합니다. \n- $a^m = a^n$이면 $m = n$ (단, $a > 0, a \\neq 1$)\n- 먼저 주어진 방정식을 정리하여 $a^f(x) = b$ 형태로 만든 후, 양변을 같은 밑의 거듭제곱으로 표현합니다.\n\n**[풀이]**\n\n**Step 1: 방정식 정리**\n$$5^{x-3}+1=26$$\n$$5^{x-3}=25$$\n\n**Step 2: 우변을 같은 밑의 거듭제곱으로 표현**\n$$25 = 5^2$$\n이므로:\n$$5^{x-3}=5^2$$\n\n**Step 3: 지수 비교**\n밑이 같으므로 지수끼리 같아야 합니다:\n$$x-3=2$$\n$$x=5$$\n\n**[정답 확인]**\n$x=5$를 원래 방정식에 대입하면: $5^{5-3}+1=5^2+1=25+1=26$ ✓\n\n**[오답 분석]**\n- **① 10**: $5^{10-3}+1=5^7+1 \\neq 26$ (훨씬 큼)\n- **③ 15**: $5^{15-3}+1=5^{12}+1$ (매우 큼)\n- **④ 12**: $5^{12-3}+1=5^9+1$ (매우 큼)\n- **⑤ 3**: $5^{3-3}+1=5^0+1=1+1=2 \\neq 26$ (지수가 음수 쪽으로 계산하는 오류)\n\n**[핵심 포인트]**\n지수방정식은 양변을 같은 밑의 거듭제곱으로 만드는 것이 핵심입니다. 먼저 상수항을 이항하여 정리한 후, 우변을 2의 거듭제곱(또는 주어진 밑의 거듭제곱)으로 표현하는 과정을 놓치지 않아야 합니다.",
