    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위해서는 먼저 지수 부분을 분리한 후, 양변을 같은 밑으로 표현하여 지수를 비교하는 방법을 사용합니다. 기본 형태는 $a^f(x) = a^g(x)$일 때 $f(x) = g(x)$입니다.\n\n**[풀이]**\n\n**Step 1: 상수항 이항**\n주어진 방정식 $3^{x-4}+2=11$에서 2를 우변으로 이항합니다.\n\n$$3^{x-4} = 11 - 2$$\n\n$$3^{x-4} = 9$$\n\n**Step 2: 우변을 같은 밑으로 표현**\n우변 9를 밑 3으로 표현합니다.\n\n$$9 = 3^2$$\n\n따라서:\n$$3^{x-4} = 3^2$$\n\n**Step 3: 지수 비교**\n양변의 밑이 같으므로 지수를 비교합니다.\n\n$$x - 4 = 2$$\n\n$$x = 6$$\n\n**[정답 확인]**\n$x=6$을 원래 방정식에 대입하면: $3^{6-4}+2 = 3^2+2 = 9+2 = 11$ ✓\n\n**[오답 분석]**\n- **① 8**: $x=8$일 때, $3^{8-4}+2 = 3^4+2 = 81+2 = 83 \\neq 11$ (틀림)\n- **② 2**: $x=2$일 때, $3^{2-4}+2 = 3^{-2}+2 = \\frac{1}{9}+2 \\neq 11$ (틀림)\n- **③ 12**: $x=12$일 때, $3^{12-4}+2 = 3^8+2 = 6561+2 = 6563 \\neq 11$ (틀림)\n- **④ 9**: $x=9$일 때, $3^{9-4}+2 = 3^5+2 = 243+2 = 245 \\neq 11$ (틀림)\n\n**[핵심 포인트]**\n지수방정식을 풀 때는 **상수항을 먼저 정리하여 지수 부분을 분리**하고, **양변을 같은 밑으로 통일**한 후 **지수를 비교**하는 세 단계가 중요합니다.",
