    "explanation": "**[핵심 개념]**\n로그의 정의를 이용하여 지수식으로 변환하는 것이 핵심입니다.\n- 로그의 정의: $\\log_a b = c$ ⟺ $a^c = b$ (단, $a > 0, a \\neq 1, b > 0$)\n- 이 문제에서는 로그 방정식을 지수 방정식으로 바꾸어 $x$의 값을 구합니다.\n\n**[풀이]**\n\n주어진 방정식: $\\log_2(x-1) = 4$\n\n**Step 1: 로그의 정의를 이용하여 지수식으로 변환**\n\n$\\log_2(x-1) = 4$는 다음과 같이 변환됩니다.\n\n$$2^4 = x - 1$$\n\n**Step 2: 지수를 계산**\n\n$$2^4 = 16$$\n\n따라서:\n$$16 = x - 1$$\n\n**Step 3: $x$ 구하기**\n\n$$x = 16 + 1 = 17$$\n\n**Step 4: 정의역 확인**\n\n로그함수 $\\log_2(x-1)$이 정의되려면 $x - 1 > 0$, 즉 $x > 1$이어야 합니다.\n$x = 17$은 이 조건을 만족합니다. ✓\n\n**[정답 확인]**\n$x = 17$을 원래 식에 대입하면: $\\log_2(17-1) = \\log_2 16 = \\log_2 2^4 = 4$ ✓\n\n**[오답 분석]**\n\n- **① 19**: $\\log_2(19-1) = \\log_2 18 \\neq 4$ (18은 2의 거듭제곱이 아님)\n- **② 22**: $\\log_2(22-1) = \\log_2 21 \\neq 4$ (21은 2의 거듭제곱이 아님)\n- **④ 20**: $\\log_2(20-1) = \\log_2 19 \\neq 4$ (19는 2의 거듭제곱이 아님)\n- **⑤ 21**: $\\log_2(21-1) = \\log_2 20 \\neq 4$ (20은 2의 거듭제곱이 아님)\n\n**[핵심 포인트]**\n- 로그 방정식은 **로그의 정의를 이용하여 지수식으로 변환**하면 쉽게 풀 수 있습니다.\n- 풀이 후 항상 로그함수의 정의역 조건($x - 1 > 0$)을 확인하는 습관을 들이세요.",
