    "explanation": "**[핵심 개념]**\n로그의 정의를 이용하여 지수 형태로 변환하는 것이 핵심입니다.\n- $\\log_a b = c$ 는 $a^c = b$ 와 동치입니다.\n- 이 성질을 이용하면 로그 방정식을 지수 방정식으로 바꾸어 풀 수 있습니다.\n\n**[풀이]**\n\n주어진 방정식: $\\log_{3}(x-1)=6$\n\n로그의 정의에 의해 이를 지수 형태로 변환하면:\n$$3^6 = x - 1$$\n\n$3^6$을 계산합니다:\n$$3^6 = 3 \\times 3 \\times 3 \\times 3 \\times 3 \\times 3$$\n\n단계적으로 계산하면:\n- $3^2 = 9$\n- $3^3 = 27$\n- $3^4 = 81$\n- $3^5 = 243$\n- $3^6 = 729$\n\n따라서:\n$$729 = x - 1$$\n\n양변에 1을 더하면:\n$$x = 730$$\n\n**[정답 확인]**\n$x = 730$을 원래 식에 대입하면 $\\log_3(730-1) = \\log_3(729) = \\log_3(3^6) = 6$ ✓\n\n**[오답 분석]**\n- ① 720: $3^6 = 729$를 계산하지 못하고 대략적인 값으로 선택한 경우\n- ③ 726: 계산 과정에서 $3^6$의 값을 잘못 구한 경우\n- ④ 725: 계산 실수로 $3^6 = 728$로 잘못 계산한 경우\n- ⑤ 724: 계산 실수로 $3^6$을 과소평가한 경우\n\n**[핵심 포인트]**\n$\\log_a b = c \\Leftrightarrow a^c = b$ 의 동치 관계를 정확히 적용하고, $3^6 = 729$를 정확히 계산하는 것이 중요합니다.",
