    "answer": 2,
    "explanation": "**[핵심 개념]**\n역함수의 정의에 따르면 $f(a) = b$일 때 $g(b) = a$입니다. 즉, $g$는 $f$의 역함수이므로 $f(g(x)) = x$가 성립합니다. 역함수를 구하는 방법은 $y = f(x)$에서 $x$와 $y$를 바꾼 후 $y$를 $x$에 대해 정리하는 것입니다.\n\n**[풀이]**\n\n**Step 1: 역함수 $g$ 구하기**\n\n$f(x) = 2^{x-3} + 4$이므로, 역함수를 구하기 위해 $y = 2^{x-3} + 4$로 놓고 $x$에 대해 정리합니다.\n\n$$y = 2^{x-3} + 4$$\n\n$$y - 4 = 2^{x-3}$$\n\n양변에 로그를 취합니다:\n\n$$\\log_2(y-4) = x - 3$$\n\n$$x = \\log_2(y-4) + 3$$\n\n따라서 $x$와 $y$를 바꾸면:\n\n$$g(y) = \\log_2(y-4) + 3$$\n\n즉, $g(x) = \\log_2(x-4) + 3$\n\n**Step 2: $g(8)$ 계산하기**\n\n$$g(8) = \\log_2(8-4) + 3 = \\log_2(4) + 3 = \\log_2(2^2) + 3 = 2 + 3 = 5$$\n\n**Step 3: $g(8) + 4$ 계산하기**\n\n$$g(8) + 4 = 5 + 4 = 9$$\n\n**[정답 확인]**\n$g(8) = 5$이므로 $g(8) + 4 = 9$이며, 역함수 계산과 로그 계산이 모두 올바르게 수행되었습니다.\n\n**[오답 분석]**\n- **①번 (8)**: $g(8)$의 값 자체를 계산하지 않고 선택한 경우\n- **②번 (7)**: 계산 과정에서 $\\log_2(4) = 1$로 잘못 계산한 경우 ($1 + 3 + 4 = 8$이 되어도 맞지 않음)\n- **④번 (10)**: $g(8) = 6$으로 잘못 계산한 경우\n- **⑤번 (2)**: 역함수를 완전히 잘못 구한 경우\n\n**[핵심 포인트]**\n역함수에서 $f(a) = b \\Leftrightarrow g(b) = a$라는 관계를 활용하고, 지수 함수의 역함수는 로그 함수임을 반드시 기억할 것. 로그 계산에서 $\\log_2(4) = 2$임을 정확히 계산하는 것이 중요합니다.",
