    "answer": 1,
    "explanation": "**[핵심 개념]**\n\n역함수의 정의: 함수 $f$의 역함수 $g$는 $f(g(x)) = x$와 $g(f(x)) = x$를 만족합니다. 따라서 $g(a) = b$이면 $f(b) = a$입니다. 역함수를 구할 때는 $y = f(x)$에서 $x$와 $y$를 바꾼 후 $y$에 대해 정리합니다.\n\n**[풀이]**\n\n**Step 1: 주어진 함수 확인**\n$$f(x) = 3^{x-2} + 5$$\n\n**Step 2: 역함수의 성질 이용**\n$g(14) = k$라고 하면, 역함수의 정의에 의해:\n$$f(k) = 14$$\n\n**Step 3: 방정식 풀기**\n$$f(k) = 14$$\n$$3^{k-2} + 5 = 14$$\n$$3^{k-2} = 9$$\n$$3^{k-2} = 3^2$$\n\n지수가 같으므로 밑이 같으면 지수도 같습니다:\n$$k - 2 = 2$$\n$$k = 4$$\n\n따라서 $g(14) = 4$\n\n**Step 4: 답 구하기**\n$$g(14) + 5 = 4 + 5 = 9$$\n\n**[정답 확인]**\n\n$f(4) = 3^{4-2} + 5 = 3^2 + 5 = 9 + 5 = 14$ ✓ 이므로 $g(14) = 4$가 맞고, $g(14) + 5 = 9$입니다.\n\n**[오답 분석]**\n\n- ① 19: $g(14) = 14 + 5$로 잘못 계산한 경우\n- ③ 8: 계산 실수로 $3^{k-2} = 8$로 잘못 푼 경우\n- ④ 4: $g(14) + 5$를 계산하지 않고 $g(14)$만 답한 경우\n- ⑤ 11: $g(14) = 6$으로 잘못 계산한 경우\n\n**[핵심 포인트]**\n\n역함수 문제는 $g(a) = b \\Leftrightarrow f(b) = a$ 성질을 이용하여, 주어진 역함수값을 원함수 방정식으로 변환하여 풀면 됩니다. 지수방정식을 정확히 풀어야 합니다.",
