    "explanation": "**[핵심 개념]**\n역함수의 정의: $y = f(x)$의 역함수 $g$는 $g(f(x)) = x$를 만족하며, $y = f(x)$에서 $x = f^{-1}(y) = g(y)$입니다. 즉, $f(a) = b$이면 $g(b) = a$입니다.\n\n**[풀이]**\n\n**Step 1: 역함수의 성질 이용**\n\n$g$는 $f$의 역함수이므로, $g(7)$을 구하려면 $f(x) = 7$을 만족하는 $x$ 값을 찾으면 됩니다.\n\n왜냐하면 $f(x) = 7$이면 $g(7) = x$이기 때문입니다.\n\n**Step 2: $f(x) = 7$인 $x$ 구하기**\n\n$$f(x) = 2^{x-5} + 3 = 7$$\n\n$$2^{x-5} = 7 - 3 = 4$$\n\n$$2^{x-5} = 2^2$$\n\n$$x - 5 = 2$$\n\n$$x = 7$$\n\n**Step 3: $g(7)$ 구하기**\n\n$f(7) = 7$이므로 $g(7) = 7$\n\n**Step 4: $g(7) + 3$ 계산**\n\n$$g(7) + 3 = 7 + 3 = 10$$\n\n**[정답 확인]**\n$f(7) = 2^{7-5} + 3 = 2^2 + 3 = 4 + 3 = 7$이므로 $g(7) = 7$이 맞으며, 따라서 $g(7) + 3 = 10$입니다.\n\n**[오답 분석]**\n- **① 3**: $g(7)$의 값 자체를 잘못 구했거나 더하기를 하지 않은 경우\n- **③ 13**: $g(7) = 10$으로 계산 오류가 있은 경우\n- **④ 15**: 역함수 계산 과정에서 $2^{x-5} = 8$로 잘못 계산한 경우\n- **⑤ 17**: 더 큰 오류로 $x = 12$를 구한 경우\n\n**[핵심 포인트]**\n- 역함수 문제에서 $g(b) = a$를 구하려면 먼저 $f(a) = b$를 만족하는 $a$를 찾는 것이 핵심입니다.\n- 지수방정식을 풀 때는 밑을 같게 만들어 지수끼리 같다고 놓는 것을 잊지 말아야 합니다.",
