    "explanation": "**[핵심 개념]**\n역함수의 정의와 성질을 이해하는 것이 중요합니다. 함수 $f$의 역함수 $g$는 $f(g(x))=x$와 $g(f(x))=x$를 만족합니다. 즉, $y=f(x)$일 때 $x=g(y)$입니다. 이를 이용하여 $g(27)$의 값을 구하려면, $f$의 함숫값이 27이 되는 $x$값을 찾으면 됩니다.\n\n**[풀이]**\n\n**Step 1: 역함수의 성질 이용**\n\n$g$는 $f$의 역함수이므로, $g(27)=a$라 하면 $f(a)=27$입니다.\n따라서 $g(27)$을 구하기 위해 $f(x)=27$을 만족하는 $x$값을 찾아야 합니다.\n\n**Step 2: 방정식 $f(x)=27$ 풀기**\n\n$$f(x)=5^{x-3}+2=27$$\n\n양변에서 2를 빼면:\n$$5^{x-3}=25$$\n\n$25=5^2$이므로:\n$$5^{x-3}=5^2$$\n\n지수가 같으면 밑도 같으므로:\n$$x-3=2$$\n\n$$x=5$$\n\n**Step 3: 역함수값 확인**\n\n$f(5)=27$이므로 $g(27)=5$입니다.\n\n**Step 4: 최종 답 계산**\n\n$$g(27)+2=5+2=7$$\n\n**[정답 확인]**\n$f(5)=5^{5-3}+2=5^2+2=25+2=27$이므로 $g(27)=5$이고, $g(27)+2=7$이 맞습니다.\n\n**[오답 분석]**\n- **① 6**: $g(27)=5$를 구한 후 1을 더한 경우\n- **② 13**: 역함수 개념을 잘못 적용하여 $f(27)$ 값을 구한 경우\n- **③ 3**: $5^{x-3}=25$에서 $x-3=2$를 $x=2$로 잘못 계산한 경우\n- **⑤ 17**: 계산 과정에서 실수가 있었던 경우\n\n**[핵심 포인트]**\n역함수 $g(a)=b$ ⟺ $f(b)=a$ 관계를 정확히 파악하고, 지수방정식 $5^{x-3}=5^2$에서 지수를 비교하여 $x$값을 구하는 것이 핵심입니다.",
