    "explanation": "**[핵심 개념]**\n1. 점의 대칭: 점 $(a, b)$를 직선 $y=x$에 대칭시키면 $(b, a)$가 된다.\n2. 좌표축에 평행한 직사각형: 두 점이 대각선의 양 끝점일 때, 직사각형의 넓이는 $|x_1 - x_2| \\times |y_1 - y_2|$이다.\n\n**[풀이]**\n\n**Step 1: 점 Q의 좌표 구하기**\n\n점 $P(2, 4)$를 직선 $y=x$에 대칭시킨다.\n점을 $y=x$에 대칭시키면 $x$좌표와 $y$좌표가 바뀌므로:\n$$Q = (4, 2)$$\n\n**Step 2: 직사각형의 꼭짓점 결정**\n\n원점 $O(0, 0)$과 점 $Q(4, 2)$를 대각선의 양 끝점으로 하는 좌표축에 평행한 직사각형을 그린다.\n\n이 직사각형의 네 꼭짓점은:\n- $(0, 0)$\n- $(4, 0)$\n- $(4, 2)$\n- $(0, 2)$\n\n**Step 3: 직사각형의 넓이 계산**\n\n좌표축에 평행한 직사각형의 경우, 대각선의 양 끝점이 $(x_1, y_1)$과 $(x_2, y_2)$일 때:\n$$\\text{넓이} = |x_2 - x_1| \\times |y_2 - y_1|$$\n\n따라서:\n$$\\text{넓이} = |4 - 0| \\times |2 - 0| = 4 \\times 2 = 8$$\n\n**[정답 확인]**\n점 $P(2, 4)$를 $y=x$에 대칭하면 $Q(4, 2)$이고, 원점과 $Q$를 대각선 양 끝점으로 하는 직사각형의 넓이는 $4 \\times 2 = 8$이다.\n\n**[오답 분석]**\n- **②번 (7)**: $4 \\times 2 = 7$로 잘못 계산한 경우\n- **③번 (20)**: 대각선의 길이를 넓이로 착각하거나, $4 \\times 5$ 등으로 잘못 계산한 경우\n- **④번 (4)**: 한 변의 길이만으로 넓이를 계산하거나, $2 \\times 2$로 잘못 계산한 경우\n- **⑤번 (10)**: $4 \\times 2.5$ 등 계산 오류가 있는 경우\n\n**[핵심 포인트]**\n1. $y=x$에 대한 대칭은 좌표를 맞바꾸는 것 → $P(2,4) \\to Q(4,2)$\n2. 좌표축에 평행한 직사각형의 넓이 = (밑변의 길이) × (높이) = $\\Delta x \\times \\Delta y$",
