    "explanation": "**[핵심 개념]**\n두 곡선의 교점을 구하기 위해서는 두 함수를 같다고 놓고 방정식을 세워야 합니다. 지수함수 $y=a^x$의 성질과 지수 법칙 $a^{m+n}=a^m \\cdot a^n$, $a^{-x}=\\frac{1}{a^x}$를 활용하여 문제를 풀 수 있습니다.\n\n**[풀이]**\n\n**1단계: 두 곡선의 교점 P 찾기**\n\n두 곡선 $y=2^x$와 $y=2^{4-x}$의 교점에서:\n$$2^x = 2^{4-x}$$\n\n**2단계: 지수 법칙을 이용한 정리**\n\n$2^{4-x}$를 전개하면:\n$$2^x = 2^4 \\cdot 2^{-x}$$\n\n$$2^x = 16 \\cdot 2^{-x}$$\n\n**3단계: 양변에 $2^x$를 곱하기**\n\n$$2^x \\cdot 2^x = 16$$\n\n$$(2^x)^2 = 16$$\n\n**4단계: $2^x$ 값 구하기**\n\n$$2^x = 4 \\text{ (∵ $2^x > 0$)}$$\n\n**5단계: 점 P의 y좌표 구하기**\n\n점 P의 y좌표는:\n$$y = 2^x = 4$$\n\n**검증:** \n- $x = 2$일 때, $y = 2^2 = 4$ ✓\n- $y = 2^{4-2} = 2^2 = 4$ ✓\n\n**[정답 확인]**\n교점에서 두 지수함수의 값이 같아야 하므로 $2^x = 2^{4-x}$를 풀면 $2^x = 4$이고, 이것이 점 P의 y좌표입니다.\n\n**[오답 분석]**\n- **①번 (1):** $2^x = 1$이면 $x = 0$인데, 이때 $2^{4-0} = 16 \\neq 1$이므로 교점이 아님\n- **③번 (6):** 계산 과정에서 $2^x = 6$이 되는 경우를 선택한 오류\n- **④번 (5):** 지수를 더하거나 다른 계산 실수로 발생 가능\n- **⑤번 (16):** $2^{4-x}$의 계수 16을 착각하여 선택한 오류\n\n**[핵심 포인트]**\n- 지수함수의 교점은 **지수끼리 같아야 한다**는 성질을 이용: $a^p = a^q \\Rightarrow p = q$\n- $(2^x)^2 = 16$에서 $2^x = 4$를 얻는 것이 핵심이며, 최종 답은 $2^x$의 값 자체가 y좌표",
