    "explanation": "**[핵심 개념]**\n지수함수 $y=a^x$ (단, $a>1$)는 증가함수이므로, 주어진 $y$값에 대해 정확히 하나의 $x$값이 대응됩니다. 따라서 수평선 $y=c$가 곡선과 만나는 점의 $x$좌표는 지수방정식 $a^x = c$를 풀어서 구합니다.\n\n**[풀이]**\n\n**1단계: 점 A의 좌표 구하기**\n\n수평선 $y=8$이 곡선 $y=2^x$와 만나는 점 $A$의 $x$좌표를 $x_A$라 하면:\n$$2^{x_A} = 8$$\n\n$8 = 2^3$이므로:\n$$2^{x_A} = 2^3$$\n$$x_A = 3$$\n\n따라서 점 $A$의 좌표는 $(3, 8)$입니다.\n\n**2단계: 점 B의 좌표 구하기**\n\n수평선 $y=8$이 곡선 $y=2^{x-1}$과 만나는 점 $B$의 $x$좌표를 $x_B$라 하면:\n$$2^{x_B-1} = 8$$\n\n$8 = 2^3$이므로:\n$$2^{x_B-1} = 2^3$$\n\n지수가 같으므로:\n$$x_B - 1 = 3$$\n$$x_B = 4$$\n\n따라서 점 $B$의 좌표는 $(4, 8)$입니다.\n\n**3단계: 두 점의 x좌표의 합**\n\n$$x_A + x_B = 3 + 4 = 7$$\n\n**[정답 확인]**\n점 $A(3, 8)$은 $y=2^3=8$을 만족하고, 점 $B(4, 8)$은 $y=2^{4-1}=2^3=8$을 만족하므로 $x_A + x_B = 7$이 정답입니다.\n\n**[오답 분석]**\n- **① 5**: $3+4-2$ 계산 실수 또는 지수 계산을 잘못함\n- **② 6**: $3+4-1$ 계산 오류 또는 한 점의 $x$좌표만 구함\n- **③ 1**: $4-3$ 계산으로 차를 구함 (합이 아님)\n- **④ 10**: $3+4+3$ 등 잘못된 값을 더함\n\n**[핵심 포인트]**\n지수함수에서 $a^p = a^q$이면 $p=q$임을 이용하여 지수끼리 같다고 놓는 것이 핵심입니다. 또한 $y=2^{x-1}$은 $y=2^x$를 오른쪽으로 1만큼 평행이동한 것이므로, 같은 높이 $y=8$에서 $x$좌표 차이는 1입니다.",
