    "explanation": "**[핵심 개념]**\n두 점을 지나는 직선의 기울기는 $m = \\frac{y_2 - y_1}{x_2 - x_1}$로 구합니다. 이는 직선의 기울기의 기본 정의로, 두 점 사이의 수직 변화량을 수평 변화량으로 나눈 값입니다.\n\n**[풀이]**\n주어진 두 점이 $A(0, 1)$과 $B(2, 4)$입니다.\n\n먼저 이 두 점이 곡선 $y = 2^x$ 위에 있는지 확인합니다:\n- 점 $A$: $x = 0$일 때, $y = 2^0 = 1$ ✓\n- 점 $B$: $x = 2$일 때, $y = 2^2 = 4$ ✓\n\n두 점을 지나는 직선의 기울기 $m$을 구합니다:\n\n$$m = \\frac{y_B - y_A}{x_B - x_A} = \\frac{4 - 1}{2 - 0} = \\frac{3}{2}$$\n\n따라서 $2m$의 값은:\n\n$$2m = 2 \\times \\frac{3}{2} = 3$$\n\n**[정답 확인]**\n두 점 $A(0, 1)$과 $B(2, 4)$를 지나는 직선의 기울기는 $\\frac{3}{2}$이므로, $2m = 3$이 정답입니다.\n\n**[오답 분석]**\n- ① $5$: 계산 오류 (예: $\\frac{5}{2}$로 잘못 계산)\n- ② $7$: 분자와 분모를 잘못 계산한 경우\n- ③ $2$: 기울기 $m$의 값으로 착각한 경우 (실제로는 $m = \\frac{3}{2}$)\n- ④ $6$: $3 \\times 2$를 다시 계산한 오류\n\n**[핵심 포인트]**\n두 점의 좌표가 주어졌을 때, 기울기는 $\\frac{\\Delta y}{\\Delta x}$로 직접 계산하면 됩니다. 이 문제는 지수함수 위의 두 점이지만, 본질적으로는 기울기 공식을 적용하는 기초 문제입니다.",
