    "explanation": "**[핵심 개념]**\n합성함수의 계산: $f(g(2))$는 먼저 $g(2)$의 값을 구한 후, 그 결과를 $f$의 입력값으로 대입하는 것입니다.\n- 로그함수: $\\log_a b$는 \"$a$를 몇 제곱하면 $b$가 되는가\"를 나타냅니다.\n- 지수함수: $a^x$는 밑 $a$를 $x$번 곱한 값입니다.\n\n**[풀이]**\n\n$f(g(2))$를 구하기 위해 단계적으로 계산합니다.\n\n**1단계: $g(2)$ 계산**\n\n$$g(x) = 2^x + 1$$\n\n$x=2$를 대입하면:\n$$g(2) = 2^2 + 1 = 4 + 1 = 5$$\n\n**2단계: $f(5)$ 계산**\n\n$$f(x) = \\log_2(x-1)$$\n\n$x=5$를 대입하면:\n$$f(5) = \\log_2(5-1) = \\log_2 4$$\n\n**3단계: $\\log_2 4$ 계산**\n\n$\\log_2 4$는 \"2를 몇 제곱하면 4가 되는가\"를 의미합니다.\n\n$$2^2 = 4 \\text{이므로}$$\n$$\\log_2 4 = 2$$\n\n따라서 $f(g(2)) = 2$\n\n**[정답 확인]**\n$f(g(2)) = f(5) = \\log_2 4 = 2$이므로 정답은 ④번입니다.\n\n**[오답 분석]**\n- **① 3**: $\\log_2 8 = 3$인데, $g(2) = 5$이고 $f(5) = \\log_2 4 \\neq \\log_2 8$\n- **② 5**: $g(2) = 5$의 값 자체를 선택한 오류 (합성함수를 계산하지 않음)\n- **③ 1**: $\\log_2 2 = 1$인데, $f(5) = \\log_2 4 \\neq \\log_2 2$\n- **⑤ 6**: 계산 과정에서의 오류로 나타나는 선택지\n\n**[핵심 포인트]**\n합성함수 $f(g(2))$는 **안쪽부터 바깥쪽으로** 계산합니다: 먼저 $g(2)$를 구하고, 그 결과를 $f$에 대입합니다.",
