    "problem": "방정식 $2^{2x}-10\\cdot 2^x+16=0$의 서로 다른 두 실근을 $\\alpha&lt;\\beta$라 한다. $x$축 위의 점 $A(\\alpha,0)$, $B(\\beta,0)$에 대하여 $AB$의 값은?",
