    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위해 치환을 이용합니다. $2^x = t$로 놓으면 지수방정식을 이차방정식으로 변환할 수 있습니다. 이차방정식의 근과 계수의 관계를 이용하면 근의 합과 곱을 구할 수 있으며, 이를 통해 두 근 사이의 거리를 계산할 수 있습니다.\n\n**[풀이]**\n\n**Step 1: 치환을 이용한 이차방정식 변환**\n\n$2^x = t$로 놓으면 ($t > 0$), 주어진 방정식은:\n$$t^2 - 10t + 16 = 0$$\n\n**Step 2: 이차방정식 풀이**\n\n근의 공식을 사용하거나 인수분해하면:\n$$t^2 - 10t + 16 = (t-2)(t-8) = 0$$\n\n따라서 $t = 2$ 또는 $t = 8$\n\n**Step 3: 원래 변수로 복원**\n\n$2^x = 2$에서 $x = 1$\n\n$2^x = 8 = 2^3$에서 $x = 3$\n\n**Step 4: $\\alpha$와 $\\beta$ 결정**\n\n$\\alpha < \\beta$이므로:\n- $\\alpha = 1$\n- $\\beta = 3$\n\n**Step 5: 두 점 사이의 거리 계산**\n\n$A(\\alpha, 0) = A(1, 0)$, $B(\\beta, 0) = B(3, 0)$\n\n$x$축 위의 두 점 사이의 거리는:\n$$AB = |\\beta - \\alpha| = |3 - 1| = 2$$\n\n**[정답 확인]**\n$2^x = t$로 치환하여 얻은 이차방정식 $t^2 - 10t + 16 = 0$의 두 근이 $t = 2, 8$이므로 원래 방정식의 근은 $x = 1, 3$이고, 따라서 $AB = 3 - 1 = 2$입니다.\n\n**[오답 분석]**\n- **① 1**: $\\beta - \\alpha = 3 - 1 = 2$를 계산하지 못하고 임의로 선택한 경우\n- **② 6**: 근과 계수의 관계에서 근의 합 10을 거리로 착각한 경우\n- **③ 10**: 이차방정식의 계수 $-10$을 직접 선택한 경우\n- **④ 7**: $\\alpha + \\beta = 4$를 계산 오류로 7로 잘못 구한 경우\n\n**[핵심 포인트]**\n지수방정식은 치환 $a^x = t$ ($t > 0$)를 통해 다항방정식으로 변환하여 풀며, 구한 $t$값을 다시 로그 또는 지수 형태로 복원하여 원래 미지수의 값을 구해야 합니다.",
