    "answer": 4,
    "explanation": "**[핵심 개념]**\n로그의 성질을 이용하여 방정식을 정리하는 문제입니다. 주요 개념은 다음과 같습니다.\n- 로그의 덧셈 법칙: $\\log_a M + \\log_a N = \\log_a(MN)$\n- 로그 방정식의 해: $\\log_a M = \\log_a N$ ⟹ $M = N$ (단, $M > 0, N > 0$)\n- 정의역 조건: 로그의 진수는 항상 양수여야 함\n\n**[풀이]**\n\n**Step 1: 로그의 덧셈 법칙 적용**\n\n$$\\log_{2}(x-1)+\\log_{2}(9-x)=\\log_{2}12$$\n\n좌변의 로그를 합치면:\n$$\\log_{2}[(x-1)(9-x)]=\\log_{2}12$$\n\n**Step 2: 로그 방정식 풀기**\n\n밑이 같으므로 진수끼리 같아야 합니다:\n$$(x-1)(9-x)=12$$\n\n**Step 3: 이차방정식으로 전개**\n\n좌변을 전개합니다:\n$$9x - x^2 - 9 + x = 12$$\n$$-x^2 + 10x - 9 = 12$$\n$$-x^2 + 10x - 21 = 0$$\n$$x^2 - 10x + 21 = 0$$\n\n**Step 4: 인수분해**\n\n$$x^2 - 10x + 21 = (x-3)(x-7) = 0$$\n\n따라서 $x = 3$ 또는 $x = 7$\n\n**Step 5: 정의역 확인**\n\n로그의 진수 조건:\n- $x - 1 > 0$ ⟹ $x > 1$\n- $9 - x > 0$ ⟹ $x < 9$\n\n따라서 $1 < x < 9$\n\n두 근 $x=3, x=7$ 모두 정의역에 포함됩니다.\n\n**Step 6: $\\alpha + \\beta$ 계산**\n\n$\\alpha < \\beta$이므로 $\\alpha = 3, \\beta = 7$\n\n$$\\alpha + \\beta = 3 + 7 = 10$$\n\n**[정답 확인]**\n이차방정식 $x^2 - 10x + 21 = 0$의 두 근의 합은 비에타 공식에 의해 $-\\frac{-10}{1} = 10$이며, 두 근 모두 정의역 조건을 만족합니다.\n\n**[오답 분석]**\n- ① $16$: 정의역을 고려하지 않고 계산한 경우\n- ② $15$: 계산 실수로 인한 오답\n- ③ $11$: 근과 계수의 관계를 잘못 적용한 경우\n- ④ $9$: 한 근만 더한 경우 ($3+6=9$로 잘못 계산)\n\n**[핵심 포인트]**\n로그 방정식을 풀 때는 ① 로그의 성질을 이용해 진수 조건식을 만들고, ② 나온 모든 근이 정의역 조건($1 < x < 9$)을 만족하는지 반드시 확인해야 합니다.",
