    "explanation": "**[핵심 개념]**\n지수함수 위의 점의 좌표를 구하는 방법과 좌표축에 내린 수선의 발의 의미를 이해해야 합니다.\n- 함수 $y=f(x)$ 위의 점에서 $x$좌표가 $a$일 때, $y$좌표는 $f(a)$입니다.\n- 점 $P(x_0, y_0)$에서 $x$축에 내린 수선의 발은 $H(x_0, 0)$이고, $y$축에 내린 수선의 발은 $K(0, y_0)$입니다.\n\n**[풀이]**\n\n**1단계: 점 A의 좌표 구하기**\n\n점 $A$는 $y=2^{x-1}$ 위의 점이고 $x$좌표가 $4$이므로, $y$좌표를 구합니다.\n\n$$y = 2^{4-1} = 2^3 = 8$$\n\n따라서 점 $A$의 좌표는 $A(4, 8)$입니다.\n\n**2단계: 수선의 발 확인하기**\n\n점 $A(4, 8)$에서 두 좌표축에 내린 수선의 발:\n- $x$축에 내린 수선의 발: $H(4, 0)$\n- $y$축에 내린 수선의 발: $K(0, 8)$\n\n(이 정보는 직사각형을 만드는 보조정보이며, 문제의 핵심은 점 $A$의 좌표를 구하는 것입니다.)\n\n**3단계: 점 A의 두 좌표의 합 구하기**\n\n$$x\\text{좌표} + y\\text{좌표} = 4 + 8 = 12$$\n\n**[정답 확인]**\n점 $A$의 좌표 $(4, 8)$에서 두 좌표의 합은 $4 + 8 = 12$이므로 정답은 ⑤번입니다.\n\n**[오답 분석]**\n- ① 24: $4 \\times 8 = 32$로 착각하거나 계산 실수\n- ② 10: $4 + 8 = 12$를 $10$으로 잘못 계산\n- ③ 18: $2^{4-1} = 10$으로 잘못 계산하여 $4 + 10 = 14$를 더 계산 오류\n- ④ 17: $2^{4-1}$을 다른 값으로 오계산\n\n**[핵심 포인트]**\n지수함수에서 $x$좌표가 주어졌을 때 $y$좌표는 함수식에 대입하여 계산합니다. 이 문제에서는 $2^3 = 8$을 정확히 계산하는 것이 가장 중요합니다.",
