    "explanation": "**[핵심 개념]**\n두 곡선의 교점을 구하기 위해서는 두 함수가 같아지는 $x$ 값을 찾아야 한다. 로그의 성질을 이용하여 방정식을 풀고, $x$축에 내린 수선의 발은 교점의 $x$좌표와 같은 점이다.\n\n**[풀이]**\n\n**단계 1: 두 곡선의 교점에서 함수값이 같음**\n\n교점 $P$에서 두 곡선의 $y$값이 같으므로:\n$$\\log_{2}(x-1) = \\log_{2}(7-x)$$\n\n**단계 2: 로그 방정식 풀기**\n\n밑이 같은 로그가 같으면 진수도 같다:\n$$x - 1 = 7 - x$$\n\n**단계 3: $x$ 값 구하기**\n\n$$x + x = 7 + 1$$\n$$2x = 8$$\n$$x = 4$$\n\n**단계 4: 정의역 확인**\n\n$x = 4$일 때:\n- $y = \\log_{2}(4-1) = \\log_{2}(3)$ (정의됨)\n- $y = \\log_{2}(7-4) = \\log_{2}(3)$ (정의됨, 일치함)\n\n따라서 $x = 4$는 유효한 해이다.\n\n**단계 5: 수선의 발과 거리**\n\n점 $P$에서 $x$축에 내린 수선의 발을 $H$라 하면, $H$의 좌표는 $(4, 0)$이다.\n\n원점 $O$에서 점 $H(4, 0)$까지의 거리는:\n$$OH = 4$$\n\n**[정답 확인]**\n교점의 $x$좌표가 4이고, $x$축 위의 점이므로 $OH = 4$이다.\n\n**[오답 분석]**\n- ① $0$: 교점이 원점에 있다는 오류\n- ② $9$: 계산 실수 ($x-1 + 7-x = 6$을 $x$로 착각)\n- ③ $14$: 두 진수의 합을 구한 오류 ($(x-1) + (7-x) = 6$)\n- ④ $1$: $7-1=6$을 2로 나눈 오류\n\n**[핵심 포인트]**\n로그 방정식에서 밑이 같으면 진수도 같다는 성질을 이용하여 직접 $x$를 구한다. $x$축에 내린 수선의 발은 같은 $x$좌표를 가지므로 교점의 $x$좌표가 곧 거리이다.",
