    "problem": "곡선 $y=\\log_{2}(x-1)$의 $x$절편을 $A$라 하고, 곡선 위의 점 $B$의 $x$좌표가 $9$라 한다. $B$에서 $x$축에 내린 수선의 발을 $H$라 할 때 선분 $AH$의 길이는?",
