    "_type": "inverse_func",
    "type": "역함수 대칭·행렬식·삼각형 넓이",
    "problem": "$y=2^x$의 점 $P(2,4)$와 역함수 $y=\\log_{2}x$의 점 $Q(4,2)$ 및 원점 $O$로 만든 삼각형의 넓이는?",
    "answerType": "choice",
    "choices": [
      "$10$",
      "$8$",
      "$4$",
      "$2$",
      "$6$"
    ],
    "answer": 4,
    "explanation": "**[핵심 개념]**\n세 점으로 만든 삼각형의 넓이를 구하는 방법으로는 다음 공식을 사용합니다.\n세 점 $O(0,0)$, $P(x_1, y_1)$, $Q(x_2, y_2)$로 만든 삼각형의 넓이는:\n$$\\text{넓이} = \\frac{1}{2}|x_1 y_2 - x_2 y_1|$$\n\n또는 벡터의 외적을 이용하여 $\\frac{1}{2}|\\vec{OP} \\times \\vec{OQ}|$로 계산할 수 있습니다.\n\n**[풀이]**\n\n주어진 세 점은 $O(0,0)$, $P(2,4)$, $Q(4,2)$입니다.\n\n**방법 1: 공식 직접 적용**\n\n$$\\text{넓이} = \\frac{1}{2}|x_P \\cdot y_Q - x_Q \\cdot y_P|$$\n$$= \\frac{1}{2}|2 \\times 2 - 4 \\times 4|$$\n$$= \\frac{1}{2}|4 - 16|$$\n$$= \\frac{1}{2}|-12|$$\n$$= \\frac{1}{2} \\times 12$$\n$$= 6$$\n\n**방법 2: 벡터의 외적 (검증)**\n\n$\\vec{OP} = (2, 4)$, $\\vec{OQ} = (4, 2)$\n\n2차원 벡터의 외적(또는 행렬식):\n$$\\vec{OP} \\times \\vec{OQ} = \\begin{vmatrix} 2 & 4 \\\\ 4 & 2 \\end{vmatrix} = 2 \\times 2 - 4 \\times 4 = 4 - 16 = -12$$\n\n$$\\text{넓이} = \\frac{1}{2}|-12| = 6$$\n\n**[정답 확인]**\n두 가지 방법 모두 넓이 = 6을 얻었으므로 답은 **⑤번 $6$**입니다.\n\n**[오답 분석]**\n- $10$: 계산 실수로 $|4-16|$을 $20$으로 잘못 계산한 경우\n- $8$: 외적 값의 절댓값 $12$를 2로 나누지 않고 다른 방식으로 계산한 경우\n- $4$: $|4-16| = 12$를 $\\frac{1}{2}$로 곱하지 않은 경우\n- $2$: 절댓값 계산 오류 또는 계산 실수\n\n**[핵심 포인트]**\n원점을 포함하는 삼각형의 넓이는 나머지 두 점의 좌표 $(x_1, y_1)$, $(x_2, y_2)$를 이용하여 $\\frac{1}{2}|x_1y_2 - x_2y_1|$로 빠르게 계산할 수 있습니다. 절댓값을 반드시 취해야 함을 잊지 마세요.",
