    "explanation": "**[핵심 개념]**\n- 역함수의 정의: 함수 $f$와 역함수 $g$의 관계는 $g(f(x))=x$, $f(g(x))=x$\n- 점의 $y=x$에 대한 대칭: 점 $(a,b)$를 $y=x$에 대칭하면 $(b,a)$가 됨\n- 함수 위의 점: 점 $(a,b)$가 함수 $f$ 위에 있으면 $f(a)=b$\n- 가로 거리: 두 점의 $x$좌표 차이의 절댓값\n\n**[풀이]**\n\n**1단계: 주어진 함수와 점 확인**\n\n$f(x)=2^{x-1}$이고, 점 $P(3,4)$가 $f$ 위의 점인지 확인합니다.\n$$f(3)=2^{3-1}=2^2=4$$\n따라서 $P(3,4)$는 $f$ 위의 점입니다. ✓\n\n**2단계: 점 $P$를 $y=x$에 대칭한 점 $Q$ 구하기**\n\n점 $P(3,4)$를 $y=x$에 대칭하면:\n$$Q(4,3)$$\n\n**3단계: 점 $Q$가 역함수 위의 점임을 확인**\n\n함수와 역함수의 그래프는 $y=x$에 대칭이므로, $P(3,4)$가 $f$ 위의 점이면 $Q(4,3)$은 역함수 $g$ 위의 점입니다.\n$$g(4)=3$$\n\n이를 확인하면: $f(3)=4$이므로 $g(4)=3$ ✓\n\n**4단계: 두 점 $P$와 $Q$ 사이의 가로 거리 계산**\n\n가로 거리는 두 점의 $x$좌표 차이입니다:\n$$|x_Q - x_P| = |4-3| = 1$$\n\n**[정답 확인]**\n점 $P(3,4)$와 그것을 $y=x$에 대칭한 점 $Q(4,3)$의 $x$좌표 차이는 1이므로, 가로 거리는 **1**입니다.\n\n**[오답 분석]**\n- **②11**: 두 점 사이의 직선거리를 계산하거나 좌표를 잘못 읽은 경우\n- **③9**: 점의 좌표를 $y=x$에 대칭하지 않고 다른 방식으로 계산한 경우\n- **④7**: 역함수의 개념을 혼동하여 잘못된 계산을 한 경우\n- **⑤2**: 가로 거리의 정의를 잘못 이해한 경우\n\n**[핵심 포인트]**\n- **함수와 역함수의 그래프는 $y=x$에 대칭**이므로, $f$ 위의 점 $(a,b)$는 $g$ 위의 점 $(b,a)$와 대응됩니다.\n- 가로 거리는 단순히 $x$좌표의 차이이므로 복잡하게 생각할 필요 없습니다.",
