    "explanation": "**[핵심 개념]**\n1. 지수함수의 성질: $f(x) = 2^{x-a} + b$ 형태에서 계수와 상수항을 구하는 방법\n2. 역함수의 정의: $g$가 $f$의 역함수이면 $f(g(x)) = x$이고 $g(f(x)) = x$\n3. 역함수 구하기: $y = f(x)$에서 $x$와 $y$를 바꾸어 $x = f(y)$로 만든 후 $y$에 대해 정리\n\n**[풀이]**\n\n**Step 1: 주어진 조건으로 $a$, $b$ 구하기**\n\n$f(x) = 2^{x-a} + b$이고 $f(1) = 5$, $f(3) = 8$이므로:\n\n$$f(1) = 2^{1-a} + b = 5 \\cdots (1)$$\n$$f(3) = 2^{3-a} + b = 8 \\cdots (2)$$\n\n식 (2) - 식 (1):\n$$2^{3-a} - 2^{1-a} = 3$$\n$$2^{1-a}(2^2 - 1) = 3$$\n$$2^{1-a} \\cdot 3 = 3$$\n$$2^{1-a} = 1 = 2^0$$\n$$1 - a = 0$$\n$$a = 1$$\n\n$a = 1$을 식 (1)에 대입:\n$$2^{1-1} + b = 5$$\n$$2^0 + b = 5$$\n$$1 + b = 5$$\n$$b = 4$$\n\n따라서 $f(x) = 2^{x-1} + 4$\n\n**Step 2: 역함수 $g$ 구하기**\n\n$y = 2^{x-1} + 4$에서 $x$와 $y$를 바꾸면:\n$$x = 2^{y-1} + 4$$\n$$x - 4 = 2^{y-1}$$\n$$\\log_2(x-4) = y - 1$$\n$$y = \\log_2(x-4) + 1$$\n\n따라서 $g(x) = \\log_2(x-4) + 1$\n\n**Step 3: $g(12)$ 계산**\n\n$$g(12) = \\log_2(12-4) + 1$$\n$$= \\log_2 8 + 1$$\n$$= \\log_2 2^3 + 1$$\n$$= 3 + 1$$\n$$= 4$$\n\n**Step 4: $a + b + g(12)$ 계산**\n\n$$a + b + g(12) = 1 + 4 + 4 = 9$$\n\n**[정답 확인]**\n$a = 1$, $b = 4$, $g(12) = 4$를 구한 후 모두 더하면 $1 + 4 + 4 = 9$이므로 정답은 ④번입니다.\n\n**[오답 분석]**\n- ① $17$: $a + b + g(12)$를 계산할 때 $g(12)$를 잘못 구한 경우 (예: $g(12) = 12$ 등으로 잘못 계산)\n- ② $5$: 주어진 조건 $f(1) = 5$와 헷갈려서 선택한 경우\n- ③ $12$: $f(3) = 8$의 값이나 다른 중간값을 최종 답으로 착각한 경우\n- ④ $9$: **정답** ✓\n\n**[핵심 포인트]**\n1. 지수함수의 조건식 두 개를 빼서 지수의 계수를 먼저 구하는 것이 핵심\n2. 역함수를 구할 때는 $x$와 $y$를 바꾼 후 $y$에 대해 정리하되, 로그를 이용하여 지수를 내려야 함",
