    "problem": "두 곡선 $y=3^x$, $y=3^{4-x}$의 교점을 $P$라 한다. $P$에서 $x$축과 $y$축에 내린 수선의 발을 각각 $H,K$라 할 때, 삼각형 $OPH$의 넓이의 2배는? (단, $O$는 원점)",
