    "answer": 4,
    "explanation": "**[핵심 개념]**\n지수함수의 교점을 구하기 위해 지수방정식을 풀어야 한다. 두 지수함수 $y=3^x$와 $y=3^{4-x}$가 만나는 점에서 $y$ 값이 같으므로 $3^x = 3^{4-x}$를 만족한다. 이를 풀면 $x$를 구할 수 있다. 또한 삼각형의 넓이는 $\\frac{1}{2} \\times \\text{밑변} \\times \\text{높이}$로 계산한다.\n\n**[풀이]**\n\n**Step 1: 교점 P의 좌표 구하기**\n\n두 곡선의 교점에서 $y$ 값이 같으므로:\n$$3^x = 3^{4-x}$$\n\n지수가 같으면 밑이 같을 때 지수끼리 같으므로:\n$$x = 4-x$$\n$$2x = 4$$\n$$x = 2$$\n\n$x=2$일 때 $y$ 좌표:\n$$y = 3^2 = 9$$\n\n따라서 교점 $P$의 좌표는 $P(2, 9)$\n\n**Step 2: 수선의 발 구하기**\n\n점 $P(2, 9)$에서:\n- $x$축에 내린 수선의 발: $H(2, 0)$\n- $y$축에 내린 수선의 발: $K(0, 9)$\n\n**Step 3: 삼각형 OPH의 넓이 구하기**\n\n삼각형 $OPH$의 꼭짓점:\n- $O(0, 0)$\n- $P(2, 9)$\n- $H(2, 0)$\n\n이 삼각형은 직각삼각형이다. ($H$에서 직각)\n- 밑변 $OH$의 길이: $2$ (원점에서 점 $H$까지의 거리)\n- 높이 $HP$의 길이: $9$ (점 $H$에서 점 $P$까지의 거리)\n\n삼각형 $OPH$의 넓이:\n$$\\text{넓이} = \\frac{1}{2} \\times 2 \\times 9 = 9$$\n\n**Step 4: 넓이의 2배 구하기**\n\n$$\\text{넓이의 2배} = 2 \\times 9 = 18$$\n\n**[정답 확인]**\n\n교점 $P(2, 9)$에서 삼각형 $OPH$의 넓이는 9이고, 이의 2배는 18이므로 정답 ⑤가 맞다.\n\n**[오답 분석]**\n\n- ① 17: 계산 과정에서 실수하여 넓이를 잘못 구한 경우\n- ② 30: 삼각형 $OPK$의 넓이($\\frac{1}{2} \\times 9 \\times 2 = 9$)를 다르게 계산하거나, 다른 도형의 넓이를 구한 경우\n- ③ 12: 넓이 계산에서 $\\frac{1}{2} \\times 2 \\times 9$를 잘못 계산한 경우\n- ④ 10: 좌표값을 잘못 이해하여 계산한 경우\n\n**[핵심 포인트]**\n\n지수방정식 $3^x = 3^{4-x}$에서 밑이 같으므로 지수끼리 같다는 조건($x = 4-x$)을 사용하여 교점의 $x$좌표를 구한다. 삼각형의 넓이를 구할 때는 직각삼각형임을 인식하고 직각을 이루는 두 변을 밑변과 높이로 사용하면 계산이 간단해진다.",
