    "explanation": "**[핵심 개념]**\n지수함수의 성질과 직선이 곡선과 만나는 점의 좌표를 구하는 방법, 그리고 삼각형의 넓이를 구하는 공식이 필요합니다.\n- 지수방정식: $3^x = a$를 만족하는 $x$는 $x = \\log_3 a$\n- 삼각형의 넓이: 한 변의 길이와 높이를 알 때, $\\text{넓이} = \\frac{1}{2} \\times \\text{밑변} \\times \\text{높이}$\n\n**[풀이]**\n\n**Step 1: 점 A의 좌표 구하기**\n\n점 A는 $y = 3^x$와 $y = 27$의 교점이므로:\n$$3^x = 27 = 3^3$$\n$$x = 3$$\n\n따라서 $A(3, 27)$\n\n**Step 2: 점 B의 좌표 구하기**\n\n점 B는 $y = 3^{x-2}$와 $y = 27$의 교점이므로:\n$$3^{x-2} = 27 = 3^3$$\n$$x - 2 = 3$$\n$$x = 5$$\n\n따라서 $B(5, 27)$\n\n**Step 3: 삼각형 OAB의 넓이 계산**\n\n세 꼭짓점이 $O(0, 0)$, $A(3, 27)$, $B(5, 27)$입니다.\n\n점 A와 B의 $y$좌표가 같으므로, $AB$를 밑변으로 하면:\n- 밑변 $AB$의 길이: $|5 - 3| = 2$\n- 높이: 점 $O$에서 직선 $AB(y=27)$까지의 거리 = $27$\n\n따라서 삼각형 OAB의 넓이:\n$$\\text{넓이} = \\frac{1}{2} \\times 2 \\times 27 = 27$$\n\n**Step 4: 넓이의 2배 계산**\n\n$$\\text{넓이의 2배} = 27 \\times 2 = 54$$\n\n**[정답 확인]**\n점 A(3, 27)과 B(5, 27)이 같은 수평선 위에 있으므로 밑변이 2, 높이가 27인 삼각형이 되어 넓이는 27, 따라서 2배는 54입니다.\n\n**[오답 분석]**\n- **46**: 높이를 23으로 잘못 계산한 경우\n- **48**: 밑변을 4로, 높이를 24로 잘못 계산한 경우\n- **56**: 밑변을 $5-3=2$로 올바르게 구했으나, 높이를 28으로 잘못 계산한 경우\n- **50**: 넓이를 25로 계산한 후 2배를 한 경우 (높이 계산 오류)\n\n**[핵심 포인트]**\n- 지수방정식 $3^{x-2} = 3^3$에서 지수끼리 같다는 점을 이용하여 $x-2=3$으로 풀어야 함\n- 두 점의 $y$좌표가 같을 때는 수평선이므로, 그것을 밑변으로 삼아 넓이 계산을 간단히 할 수 있음",
