    "explanation": "**[핵심 개념]**\n이 문제는 함수의 합성과 로그 및 지수함수의 성질을 이용합니다.\n- 로그함수의 정의: $\\log_a b = c \\Leftrightarrow a^c = b$\n- 함수의 합성: $g(f(x))$는 먼저 $f(x)$를 계산한 후, 그 결과를 $g$의 입력값으로 사용\n- 지수함수와 로그함수는 역함수 관계: $a^{\\log_a x} = x$\n\n**[풀이]**\n\n**Step 1: $f(29)$ 계산**\n\n$$f(x) = \\log_3(x-2)$$\n\n$$f(29) = \\log_3(29-2) = \\log_3 27$$\n\n**Step 2: $\\log_3 27$의 값 구하기**\n\n$\\log_3 27$은 \"3을 몇 제곱하면 27이 되는가?\"를 의미합니다.\n\n$$3^3 = 27$$\n\n따라서 $\\log_3 27 = 3$\n\n즉, $f(29) = 3$\n\n**Step 3: $g(f(29)) = g(3)$ 계산**\n\n$$g(x) = 3^x + 2$$\n\n$$g(3) = 3^3 + 2 = 27 + 2 = 29$$\n\n따라서 $g(f(29)) = 29$\n\n**[정답 확인]**\n$f(29) = 3$일 때 $g(3) = 3^3 + 2 = 29$이므로 정답은 ①번입니다.\n\n**[오답 분석]**\n- **②번 (41)**: $g(5) = 3^5 + 2 = 245 + 2 = 247$이 아니고, 계산 실수로 나올 수 있음\n- **③번 (24)**: $f(29) = 3$을 올바르게 구했으나, $g(3) = 3^3 + 2$에서 $3^3 = 27$을 $24$로 잘못 계산한 경우\n- **④번 (28)**: $3^3 = 27$을 계산한 후 $+2$를 빼먹고 $27$에서 1을 뺀 경우\n- **⑤번 (30)**: $g(3) = 3^3 + 2$에서 지수를 잘못 계산하거나 연산 실수\n\n**[핵심 포인트]**\n1. 함수의 합성은 **안쪽 함수부터 먼저 계산** ($f(29)$ 먼저 구하기)\n2. 로그와 지수의 관계를 정확히 파악: $\\log_3 27 = 3 \\Leftrightarrow 3^3 = 27$",
