    "explanation": "**[핵심 개념]**\n1. 치환을 이용한 이차방정식 풀이: $2^x = t$로 치환하면 지수방정식을 이차방정식으로 변환\n2. 삼각형의 넓이 공식: 원점을 한 꼭짓점으로 하는 삼각형의 넓이는 $\\frac{1}{2}|x_1y_2 - x_2y_1|$\n\n**[풀이]**\n\n**Step 1: 주어진 방정식을 이차방정식으로 변환**\n\n$2^{2x}-20\\cdot2^x+64=0$에서 $t=2^x$로 치환하면:\n$$t^2 - 20t + 64 = 0$$\n\n**Step 2: 이차방정식 풀이**\n\n근의 공식을 사용하면:\n$$t = \\frac{20 \\pm \\sqrt{400-256}}{2} = \\frac{20 \\pm \\sqrt{144}}{2} = \\frac{20 \\pm 12}{2}$$\n\n따라서:\n$$t = 16 \\text{ 또는 } t = 4$$\n\n**Step 3: $\\alpha$, $\\beta$ 구하기**\n\n$2^x = 16$ 또는 $2^x = 4$이므로:\n$$2^x = 4 \\Rightarrow x = 2$$\n$$2^x = 16 \\Rightarrow x = 4$$\n\n$\\alpha < \\beta$이므로:\n$$\\alpha = 2, \\quad \\beta = 4$$\n\n**Step 4: 세 점의 좌표 결정**\n\n$$O = (0, 0)$$\n$$P = (\\alpha, 2^\\alpha) = (2, 2^2) = (2, 4)$$\n$$Q = (\\beta, 2^\\beta) = (4, 2^4) = (4, 16)$$\n\n**Step 5: 삼각형의 넓이 계산**\n\n원점 $O$를 한 꼭짓점으로 하므로 넓이 공식:\n$$\\text{넓이} = \\frac{1}{2}|x_P \\cdot y_Q - x_Q \\cdot y_P|$$\n$$= \\frac{1}{2}|2 \\times 16 - 4 \\times 4|$$\n$$= \\frac{1}{2}|32 - 16|$$\n$$= \\frac{1}{2} \\times 16$$\n$$= 8$$\n\n**[정답 확인]**\n치환으로 $\\alpha=2, \\beta=4$를 구하고, 원점과 두 점 $P(2,4), Q(4,16)$으로 이루는 삼각형의 넓이를 행렬식 공식으로 계산하면 정확히 8이 나온다.\n\n**[오답 분석]**\n- **12, 14**: 계산 실수로 절댓값 처리를 잘못했거나 다른 넓이 공식을 사용한 경우\n- **6**: $\\frac{1}{2}|32-16|$을 $\\frac{1}{2} \\times 12$로 잘못 계산\n- **9**: 근과 계수의 관계를 잘못 이용하거나 좌표값을 오류로 계산\n\n**[핵심 포인트]**\n1. 지수방정식은 치환을 통해 이차방정식으로 변환하여 풀기\n2. 원점을 포함한 삼각형의 넓이는 $\\frac{1}{2}|x_1y_2 - x_2y_1|$ 공식을 사용",
