    "explanation": "**[핵심 개념]**\n\n1. **역함수의 성질**: 함수 $f$와 그 역함수 $g$의 그래프는 직선 $y=x$에 대하여 대칭입니다.\n2. **점의 대칭**: 점 $(a,b)$를 직선 $y=x$에 대하여 대칭시키면 $(b,a)$가 됩니다.\n3. **거리의 합**: 두 점 $(x_1, y_1)$과 $(x_2, y_2)$의 가로 거리는 $|x_2-x_1|$, 세로 거리는 $|y_2-y_1|$입니다.\n\n**[풀이]**\n\n**Step 1: 점 P가 함수 f 위의 점임을 확인**\n\n$f(x) = 3^x$이고 $P(2,9)$가 $f$ 위의 점이므로:\n$$f(2) = 3^2 = 9 \\checkmark$$\n\n따라서 $P(2, 9)$는 올바른 점입니다.\n\n**Step 2: 역함수 g 구하기**\n\n$f(x) = 3^x$의 역함수는:\n$$y = 3^x \\Rightarrow x = 3^y \\Rightarrow y = \\log_3 x$$\n\n따라서 $g(x) = \\log_3 x$입니다.\n\n**Step 3: 점 Q 찾기**\n\n점 $P(2, 9)$를 직선 $y=x$에 대하여 대칭시키면:\n$$Q(9, 2)$$\n\n기하학적으로, $P$는 함수 $f$ 위의 점이므로 $Q$는 역함수 $g$ 위의 점이 됩니다.\n(실제로 $g(9) = \\log_3 9 = \\log_3 3^2 = 2$ ✓)\n\n**Step 4: 가로 거리와 세로 거리의 합 계산**\n\n$P(2, 9)$와 $Q(9, 2)$ 사이의:\n- 가로 거리: $|9-2| = 7$\n- 세로 거리: $|2-9| = |-7| = 7$\n\n따라서 가로 거리와 세로 거리의 합은:\n$$7 + 7 = 14$$\n\n**[정답 확인]**\n\n$y=x$에 대한 대칭은 좌표를 교환하므로 $P(2,9) \\to Q(9,2)$이고, 두 점 사이의 거리 성분의 합은 $|9-2| + |2-9| = 7 + 7 = 14$입니다.\n\n**[오답 분석]**\n\n- **②19**: 거리 계산 과정에서 실수하거나, 대각선 거리 $\\sqrt{(9-2)^2 + (2-9)^2} = 7\\sqrt{2} \\approx 9.9$를 더한 경우\n- **③6**: 한 쪽 거리만 계산한 경우 ($6+6=12$와 혼동)\n- **④22**: 거리를 중복 계산하거나 다른 점을 사용한 경우\n- **⑤20**: 계산 과정에서의 산술 오류\n\n**[핵심 포인트]**\n\n1. **역함수 그래프는 $y=x$ 대칭**: 점 $(a,b)$가 $f$ 위에 있으면 $(b,a)$는 $g$ 위에 있습니다.\n2. **좌표 교환이 핵심**: 직선 $y=x$에 대한 대칭은 단순히 $x$좌표와 $y$좌표를 바꾸는 것입니다.",
