    "problem": "$f(x)=\\begin{cases}2^{x-2}&amp;(x\\le3)\\\\ \\log_2(x-2)+2&amp;(x&gt;3)\\end{cases}$일 때 $f(f(f(4)))+f(f(3))$의 값은?",
