    "explanation": "**[핵심 개념]**\n- 지수함수의 성질: $f(x) = a^{x-p} + q$ 형태에서 $p$는 수평 이동, $q$는 수직 이동을 나타냄\n- 역함수의 정의: $g$가 $f$의 역함수이면 $f(g(x)) = x$이고 $g(f(x)) = x$\n- 역함수 구하기: $y = f(x)$에서 $x$와 $y$를 바꾸고 $y$에 대해 정리\n\n**[풀이]**\n\n**Step 1: 주어진 조건을 이용하여 p, q 구하기**\n\n$f(x) = 2^{x-p} + q$이고 $f(2) = 5$, $f(4) = 8$이다.\n\n$$f(2) = 2^{2-p} + q = 5 \\cdots (1)$$\n$$f(4) = 2^{4-p} + q = 8 \\cdots (2)$$\n\n식 (2) - 식 (1):\n$$2^{4-p} - 2^{2-p} = 3$$\n$$2^{2-p}(2^2 - 1) = 3$$\n$$2^{2-p} \\cdot 3 = 3$$\n$$2^{2-p} = 1 = 2^0$$\n$$2-p = 0$$\n$$p = 2$$\n\n식 (1)에 $p = 2$를 대입:\n$$2^{2-2} + q = 5$$\n$$2^0 + q = 5$$\n$$1 + q = 5$$\n$$q = 4$$\n\n따라서 $f(x) = 2^{x-2} + 4$\n\n**Step 2: 역함수 g(x) 구하기**\n\n$y = 2^{x-2} + 4$에서 $x$와 $y$를 바꾸면:\n$$x = 2^{y-2} + 4$$\n\n$y$에 대해 정리:\n$$x - 4 = 2^{y-2}$$\n$$\\log_2(x-4) = y - 2$$\n$$y = \\log_2(x-4) + 2$$\n\n따라서 $g(x) = \\log_2(x-4) + 2$\n\n**Step 3: g(12) 계산**\n\n$$g(12) = \\log_2(12-4) + 2$$\n$$= \\log_2 8 + 2$$\n$$= \\log_2 2^3 + 2$$\n$$= 3 + 2$$\n$$= 5$$\n\n**Step 4: p + q + g(12) 계산**\n\n$$p + q + g(12) = 2 + 4 + 5 = 11$$\n\n**[정답 확인]**\n$p=2, q=4, g(12)=5$를 구하여 합을 계산하면 $2+4+5=11$이므로 정답은 ②번이다.\n\n**[오답 분석]**\n- ①($10$): $p+q+g(12)=2+4+4$로 $g(12)$을 $\\log_2 8$의 계산 실수로 4라고 잘못 구한 경우\n- ③($13$): $p+q$를 구하는 과정에서 계산 실수 또는 $g(12)$에서 로그값을 잘못 계산\n- ④($15$): $p$나 $q$를 잘못 구한 경우 (예: $p=3$ 또는 $q=5$로 오산)\n- ⑤($14$): 역함수 계산 과정에서 상수항 처리 실수\n\n**[핵심 포인트]**\n- 지수함수에서 두 점의 함숫값을 이용할 때는 두 식을 뺄셈하여 지수 항만 남기는 전략이 효과적\n- 역함수를 구할 때 $x = 2^{y-2} + 4$에서 로그를 사용하여 지수를 없애고 $y$를 정리하는 것이 핵심",
