    "explanation": "**[핵심 개념]**\n두 곡선의 교점을 구하기 위해 두 함수를 같다고 놓고 방정식을 풀어야 합니다. 로그 함수의 성질 중 $\\log_a x = \\log_a y \\Rightarrow x = y$를 사용합니다. 또한 교점 $P$에서 $x$축에 내린 수선의 발 $H$의 좌표는 $(x_P, 0)$이고, 원점 $O$에서 $H$까지의 거리는 $|x_P|$입니다.\n\n**[풀이]**\n\n**단계 1: 교점 조건**\n두 곡선의 교점 $P$에서 다음이 성립합니다.\n$$\\log_3(x-2) = \\log_3(10-x)$$\n\n**단계 2: 로그 함수의 성질 적용**\n로그 함수는 일대일 대응이므로:\n$$x - 2 = 10 - x$$\n\n**단계 3: $x$ 값 구하기**\n$$x + x = 10 + 2$$\n$$2x = 12$$\n$$x = 6$$\n\n**단계 4: 정의역 확인**\n- $y = \\log_3(x-2)$의 정의역: $x > 2$\n- $y = \\log_3(10-x)$의 정의역: $x < 10$\n- $x = 6$은 $2 < 6 < 10$을 만족하므로 valid합니다.\n\n**단계 5: 교점 $P$의 좌표**\n교점 $P$의 $x$좌표는 $6$이고, $y$좌표는:\n$$y = \\log_3(6-2) = \\log_3 4$$\n따라서 $P = (6, \\log_3 4)$\n\n**단계 6: 점 $H$의 좌표 및 거리**\n$P$에서 $x$축에 내린 수선의 발 $H$는 $(6, 0)$입니다.\n$$OH = 6$$\n\n**단계 7: 최종 답**\n$$OH\\text{의 2배} = 2 \\times 6 = 12$$\n\n**[정답 확인]**\n교점의 $x$좌표가 6이고, 수선의 발까지의 거리가 6이므로 2배는 12가 됩니다.\n\n**[오답 분석]**\n- ② 14: $x = 7$로 잘못 계산한 경우\n- ③ 10: $x = 5$로 계산하거나 $OH$의 값을 직접 답으로 한 경우\n- ④ 2: 계산 실수로 $x = 1$을 얻은 경우 (정의역 위반)\n- ⑤ 20: $x = 10$으로 잘못 계산한 경우 (정의역 위반)\n\n**[핵심 포인트]**\n로그 함수의 교점은 로그의 진수를 같다고 놓아 구합니다. 정의역을 항상 확인하여 구한 해가 타당한지 검증해야 합니다.",
