    "explanation": "**[핵심 개념]**\n\n로그 부등식을 풀기 위해서는 다음을 알아야 합니다:\n- 로그의 정의역: $\\log_a(b)$에서 $b > 0$이어야 함\n- 로그 부등식: $0 \\le \\log_a(x) \\le n$은 $a^0 \\le x \\le a^n$과 동치 (단, $a > 1$)\n- 로그값 계산: $\\log_a(a^n) = n$\n\n**[풀이]**\n\n**Step 1: 주어진 부등식 분석**\n\n$0 \\le \\log_3(x-2) \\le 4$를 풀어야 합니다.\n\n먼저 정의역 조건: $x - 2 > 0$ ⟹ $x > 2$\n\n**Step 2: 로그 부등식을 지수 형태로 변환**\n\n$0 \\le \\log_3(x-2) \\le 4$는 다음과 같이 변환됩니다:\n\n$3^0 \\le x-2 \\le 3^4$\n\n$1 \\le x-2 \\le 81$\n\n**Step 3: $x$의 범위 구하기**\n\n양변에 2를 더하면:\n\n$1 + 2 \\le x \\le 81 + 2$\n\n$3 \\le x \\le 83$\n\n**Step 4: 정수 조건 적용**\n\n$x$는 정수이고 $3 \\le x \\le 83$을 만족해야 하므로:\n- $x$의 최솟값: $3$\n- $x$의 최댓값: $83$\n\n**Step 5: 최솟값과 최댓값의 합**\n\n$3 + 83 = 86$\n\n**[정답 확인]**\n\n$x=3$일 때: $\\log_3(3-2) = \\log_3(1) = 0$ ✓\n$x=83$일 때: $\\log_3(83-2) = \\log_3(81) = \\log_3(3^4) = 4$ ✓\n모두 $0 \\le \\log_3(x-2) \\le 4$ 범위 내에 있으므로 정답은 **86**\n\n**[오답 분석]**\n\n- **90**: $3^4 = 82$로 잘못 계산하여 최댓값을 85 이상으로 잡은 경우\n- **84**: 부등식을 $3 \\le x < 83$으로 잘못 해석하여 최댓값을 82로 계산한 경우\n- **88**: 최솟값을 2로 잘못 설정하거나 계산 오류가 있는 경우\n- **82**: 최솟값을 4로 잘못 설정한 경우\n\n**[핵심 포인트]**\n\n1. 로그 부등식 $0 \\le \\log_a(x) \\le n$은 $a^0 \\le x \\le a^n$으로 변환하는 것이 핵심\n2. $3^4 = 81$을 정확히 계산하고, 최댓값이 83임을 확인해야 함",
