    "problem": "$f(x)=3^{x-2}$의 역함수를 $g$라 한다. $f$ 위의 점 $P(4,9)$를 $y=x$에 대칭한 점 $Q$에 대하여 두 점의 가로 거리와 세로 거리의 합는?",
