    "explanation": "**[핵심 개념]**\n- 역함수의 정의: $f$의 그래프 위의 점 $(a, b)$를 $y=x$에 대칭하면 역함수 $g$의 그래프 위의 점 $(b, a)$가 된다.\n- 두 점 사이의 거리: 점 $(x_1, y_1)$과 $(x_2, y_2)$ 사이의 가로 거리는 $|x_2 - x_1|$, 세로 거리는 $|y_2 - y_1|$\n\n**[풀이]**\n\n**1단계: 주어진 함수 확인**\n$f(x) = 3^{x-2}$이고, $P(4, 9)$가 $f$ 위의 점인지 확인:\n$$f(4) = 3^{4-2} = 3^2 = 9 \\checkmark$$\n\n**2단계: 점 $P$를 $y=x$에 대칭하여 점 $Q$ 구하기**\n점 $P(4, 9)$를 직선 $y=x$에 대칭하면, $x$좌표와 $y$좌표가 바뀌므로:\n$$Q(9, 4)$$\n\n이는 역함수 $g$의 그래프 위의 점이 되며, 실제로 $g(9) = 4$임을 확인할 수 있다:\n- $f(4) = 9$이므로 $g(9) = 4$ (역함수의 정의)\n\n**3단계: 가로 거리와 세로 거리의 합 계산**\n두 점 $P(4, 9)$와 $Q(9, 4)$ 사이의:\n- 가로 거리: $|9 - 4| = 5$\n- 세로 거리: $|4 - 9| = 5$\n\n따라서 가로 거리와 세로 거리의 합:\n$$5 + 5 = 10$$\n\n**[정답 확인]**\n점 $P(4, 9)$와 $Q(9, 4)$의 가로 거리 5와 세로 거리 5의 합이 10이므로 정답은 ④번이다.\n\n**[오답 분석]**\n- **12, 15, 20**: 거리 계산을 잘못했거나 다른 점들 사이의 거리를 계산한 경우\n- **5**: 가로 거리만 계산하거나 세로 거리만 계산한 경우 (합이 아닌 하나만 답한 것)\n\n**[핵심 포인트]**\n- 점을 $y=x$에 대칭하면 좌표가 $(a, b) \\rightarrow (b, a)$로 바뀐다.\n- \"가로 거리와 세로 거리의 합\"은 두 거리를 모두 구해서 더해야 하는 문제이다.",
