    "answer": 4,
    "explanation": "**[핵심 개념]**\n로그의 정의: $\\log_a b = c$ 는 $a^c = b$를 의미합니다.\n즉, $\\log_2 32$는 \"2를 몇 제곱하면 32가 되는가?\"를 묻는 문제입니다.\n또한 2의 거듭제곱을 알아야 합니다: $2^1=2, 2^2=4, 2^3=8, 2^4=16, 2^5=32$\n\n**[풀이]**\n$\\log_2 32 = x$라고 하면, 로그의 정의에 의해:\n$$2^x = 32$$\n\n32를 2의 거듭제곱으로 나타내면:\n$$32 = 2^5$$\n\n따라서:\n$$2^x = 2^5$$\n\n지수가 같으므로:\n$$x = 5$$\n\n∴ $\\log_2 32 = 5$\n\n**[정답 확인]**\n$2^5 = 32$이므로 $\\log_2 32 = 5$가 맞습니다.\n\n**[오답 분석]**\n- ① 0: $2^0 = 1 \\neq 32$\n- ② -5: $2^{-5} = \\frac{1}{32} \\neq 32$\n- ③ 8: $2^8 = 256 \\neq 32$\n- ④ 9: $2^9 = 512 \\neq 32$\n\n**[핵심 포인트]**\n로그 $\\log_a b = c$는 $a^c = b$의 다른 표현입니다. 2의 거듭제곱을 빠르게 계산할 수 있도록 기본값들($2^5=32$)을 외워두는 것이 중요합니다.",
