    "explanation": "**[핵심 개념]**\n로그의 정의: $\\log_a b = c$ 는 $a^c = b$ 를 의미합니다.\n이 문제에서는 \"3을 몇 제곱하면 27이 되는가?\"를 구하는 것입니다.\n또한 $27 = 3^3$ 임을 알아야 합니다.\n\n**[풀이]**\n$\\log_3 27 = x$ 라고 놓으면, 로그의 정의에 의해:\n$$3^x = 27$$\n\n27을 3의 거듭제곱으로 나타내면:\n$$27 = 3 \\times 3 \\times 3 = 3^3$$\n\n따라서:\n$$3^x = 3^3$$\n\n양변의 지수가 같으므로:\n$$x = 3$$\n\n**[정답 확인]**\n$3^3 = 27$ 이므로 $\\log_3 27 = 3$ 이 맞습니다.\n\n**[오답 분석]**\n- **① 1**: $3^1 = 3$ 이므로 틀렸습니다.\n- **③ 0**: $3^0 = 1$ 이므로 틀렸습니다.\n- **④ 11**: 계산 근거가 없는 임의의 수입니다.\n- **⑤ 6**: $3 \\times 2 = 6$ 으로 착각한 경우로, $3^6 = 729 \\neq 27$ 입니다.\n\n**[핵심 포인트]**\n로그 $\\log_a b = c$ 는 \"$a$를 $c$제곱하면 $b$가 된다\"는 의미이므로, 밑을 거듭제곱하여 진수를 만드는 지수를 찾으면 됩니다.",
