    "explanation": "**[핵심 개념]**\n\n로그의 성질을 이용하여 문제를 풀어야 합니다.\n\n1. $\\log_a(a^x) = x$ (밑과 진수의 밑이 같으면 지수가 그 값)\n2. $\\log_a(x) + \\log_a(y) = \\log_a(xy)$ (곱의 로그)\n3. $\\log_a(x) - \\log_a(y) = \\log_a\\left(\\frac{x}{y}\\right)$ (몫의 로그)\n\n**[풀이]**\n\n주어진 식: $\\log_2(2^5)+\\log_2(2^3)-\\log_2 2$\n\n**Step 1: 각 항을 로그의 기본 성질을 이용해 정리**\n\n$\\log_a(a^x) = x$를 적용하면:\n- $\\log_2(2^5) = 5$\n- $\\log_2(2^3) = 3$\n- $\\log_2 2 = \\log_2(2^1) = 1$\n\n**Step 2: 계산**\n\n$$\\log_2(2^5)+\\log_2(2^3)-\\log_2 2 = 5 + 3 - 1 = 7$$\n\n또는 로그의 성질을 이용하여:\n\n$$\\log_2(2^5)+\\log_2(2^3)-\\log_2 2 = \\log_2\\left(\\frac{2^5 \\times 2^3}{2}\\right)$$\n\n$$= \\log_2\\left(\\frac{2^8}{2^1}\\right) = \\log_2(2^7) = 7$$\n\n**[정답 확인]**\n\n$\\log_2(2^5) = 5, \\log_2(2^3) = 3, \\log_2 2 = 1$이므로 $5 + 3 - 1 = 7$이 맞습니다.\n\n**[오답 분석]**\n\n- **10**: $\\log_2(2^5) + \\log_2(2^3)$만 계산하고 뺄셈을 빠뜨린 경우 ($5 + 3 + 2 = 10$으로 잘못 생각)\n- **15**: 지수를 더하면서 로그 성질을 무시한 경우\n- **-3**: 뺄셈 순서를 잘못 계산한 경우 ($1 - 3 - 5 = -7$의 절댓값으로 착각)\n- **2**: 계산 실수로 $5 + 3 - 1 = 2$로 잘못 계산\n\n**[핵심 포인트]**\n\n$\\log_a(a^x) = x$는 로그 계산의 가장 기본 성질입니다. 주어진 식의 모든 항을 먼저 이 성질로 간단히 한 후 사칙연산하면 실수를 방지할 수 있습니다.",
