    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위한 가장 기본적인 성질은 **밑이 같은 두 지수식이 같으면 지수도 같다**는 것입니다.\n즉, $a > 0$이고 $a \\neq 1$일 때, $a^m = a^n$ 이면 $m = n$ 입니다.\n이 문제에서는 양변의 밑이 모두 3으로 같으므로 지수끼리 같다고 놓을 수 있습니다.\n\n**[풀이]**\n주어진 식: $3^{x+2} = 3^7$\n\n양변의 밑이 모두 3으로 같으므로, 지수법칙에 의해 지수끼리 같아야 합니다.\n\n$$x + 2 = 7$$\n\n양변에서 2를 빼면:\n\n$$x = 7 - 2 = 5$$\n\n따라서 $x = 5$입니다.\n\n**[정답 확인]**\n$x = 5$를 원래 식에 대입하면 $3^{5+2} = 3^7$이므로 주어진 조건을 만족합니다. ✓\n\n**[오답 분석]**\n- **②번 (3)**: $x = 3$이면 $3^{3+2} = 3^5 \\neq 3^7$ (틀림)\n- **③번 (2)**: $x = 2$이면 $3^{2+2} = 3^4 \\neq 3^7$ (틀림)\n- **④번 (10)**: $x = 10$이면 $3^{10+2} = 3^{12} \\neq 3^7$ (틀림)\n- **⑤번 (4)**: $x = 4$이면 $3^{4+2} = 3^6 \\neq 3^7$ (틀림)\n\n**[핵심 포인트]**\n**밑이 같은 지수방정식은 지수만 비교하면 된다**: $a^m = a^n \\Rightarrow m = n$ (단, $a > 0, a \\neq 1$)",
