    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위해서는 같은 밑(base)을 가진 지수끼리 비교하는 성질을 이용합니다.\n- 같은 양의 수 $a$ ($a \\neq 1$)에 대해 $a^m = a^n$이면 $m = n$입니다.\n- 이를 이용하여 지수끼리 같다는 식을 세울 수 있습니다.\n\n**[풀이]**\n주어진 방정식: $3^{x+4} = 3^6$\n\n**Step 1:** 양변의 밑이 모두 3으로 같습니다.\n\n**Step 2:** 밑이 같고 양수이며 1이 아닐 때, 다음 성질을 적용합니다.\n$$3^{x+4} = 3^6 \\Rightarrow x+4 = 6$$\n\n**Step 3:** 지수를 같다고 놓은 식을 정리합니다.\n$$x + 4 = 6$$\n$$x = 6 - 4$$\n$$x = 2$$\n\n**[정답 확인]**\n$x = 2$를 원래 식에 대입하면: $3^{2+4} = 3^6$ ✓ (참)\n\n**[오답 분석]**\n- **① 3:** $x=3$이면 $3^{3+4} = 3^7 \\neq 3^6$ (지수를 더한 경우)\n- **② -6:** $x=-6$이면 $3^{-6+4} = 3^{-2} \\neq 3^6$ (우변과 비교하지 않음)\n- **③ 10:** $x=10$이면 $3^{10+4} = 3^{14} \\neq 3^6$ (지수를 잘못 계산)\n- **④ 7:** $x=7$이면 $3^{7+4} = 3^{11} \\neq 3^6$ (우변 지수를 $x$로 잘못 인식)\n\n**[핵심 포인트]**\n$a^m = a^n$ (단, $a > 0, a \\neq 1$)이면 **$m = n$**이다. 같은 밑의 지수방정식은 지수끼리 같다고 놓고 풀면 된다.",
