    "explanation": "**[핵심 개념]**\n지수방정식에서 밑이 같으면 지수가 같다는 성질을 이용합니다.\n- $a^m = a^n$ (단, $a > 0, a \\neq 1$)이면 $m = n$\n\n**[풀이]**\n주어진 방정식: $3^{x+5}=3^6$\n\n양변의 밑이 모두 3으로 같으므로, 지수끼리 같아야 합니다.\n\n$$x + 5 = 6$$\n\n양변에서 5를 빼면:\n$$x = 6 - 5 = 1$$\n\n**[정답 확인]**\n$x = 1$을 원래 식에 대입하면 $3^{1+5} = 3^6$이므로 $3^6 = 3^6$ ✓ (참)\n\n**[오답 분석]**\n- ① 7: $x = 7$이면 $3^{7+5} = 3^{12} \\neq 3^6$ (오류)\n- ② 11: $x = 11$이면 $3^{11+5} = 3^{16} \\neq 3^6$ (오류)\n- ④ 2: $x = 2$이면 $3^{2+5} = 3^7 \\neq 3^6$ (오류)\n- ⑤ 6: $x = 6$이면 $3^{6+5} = 3^{11} \\neq 3^6$ (오류)\n\n**[핵심 포인트]**\n밑이 같은 지수방정식은 지수만 같으면 되므로, 양변의 지수를 같다고 놓고 일차방정식을 푼다. 이것이 지수방정식의 가장 기본적인 풀이 방법입니다.",
