    "answer": 1,
    "explanation": "**[핵심 개념]**\n지수방정식의 기본 성질을 이용한 풀이입니다. 같은 밑을 가진 지수식에서 두 식이 같으면, 지수도 같다는 원리를 사용합니다.\n\n**지수 방정식의 성질:**\n$a^m = a^n$ (단, $a > 0, a \\neq 1$)이면 $m = n$\n\n**[풀이]**\n\n주어진 식: $3^{x+6}=3^9$\n\n**Step 1:** 양변의 밑이 모두 3으로 같습니다.\n\n**Step 2:** 밑이 같은 지수식이 같으므로, 지수끼리 같아야 합니다.\n$$x + 6 = 9$$\n\n**Step 3:** 양변에서 6을 빼서 $x$를 구합니다.\n$$x = 9 - 6 = 3$$\n\n**[정답 확인]**\n$x = 3$을 원래 식에 대입하면: $3^{3+6} = 3^9 = 3^9$ ✓\n\n**[오답 분석]**\n- **① 8:** $x + 6 = 14$가 되어 $3^{14} \\neq 3^9$\n- **③ 6:** $x + 6 = 12$가 되어 $3^{12} \\neq 3^9$\n- **④ 1:** $x + 6 = 7$이 되어 $3^7 \\neq 3^9$\n- **⑤ 5:** $x + 6 = 11$이 되어 $3^{11} \\neq 3^9$\n\n**[핵심 포인트]**\n지수방정식에서 양변의 밑이 같으면 지수를 같다고 놓으면 된다는 것이 핵심입니다. 복잡한 계산이 필요 없는 기본 성질의 활용 문제입니다.",
