    "choices": [
      "13",
      "23",
      "28",
      "18",
      "17"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n로그의 정의에 따르면 $\\log_a b = c$는 $a^c = b$와 같습니다. 따라서 주어진 로그 방정식을 지수 형태로 변환하여 풀 수 있습니다.\n\n**[풀이]**\n주어진 방정식: $\\log_2(x-2)=4$\n\n로그의 정의를 이용하여 지수 형태로 변환합니다.\n$$\\log_2(x-2)=4 \\Rightarrow 2^4 = x-2$$\n\n$2^4$를 계산합니다.\n$$2^4 = 16$$\n\n따라서:\n$$16 = x - 2$$\n\n양변에 2를 더하여 $x$를 구합니다.\n$$x = 16 + 2 = 18$$\n\n**[정답 확인]**\n$x=18$을 원래 식에 대입하면: $\\log_2(18-2) = \\log_2 16 = \\log_2 2^4 = 4$ ✓\n\n**[오답 분석]**\n- **13**: $\\log_2(13-2) = \\log_2 11 \\neq 4$ (11은 2의 거듭제곱이 아님)\n- **17**: $\\log_2(17-2) = \\log_2 15 \\neq 4$ (15는 2의 거듭제곱이 아님)\n- **23**: $\\log_2(23-2) = \\log_2 21 \\neq 4$ (21은 2의 거듭제곱이 아님)\n- **28**: $\\log_2(28-2) = \\log_2 26 \\neq 4$ (26은 2의 거듭제곱이 아님)\n\n**[핵심 포인트]**\n로그 방정식은 로그의 정의 $\\log_a b = c \\Leftrightarrow a^c = b$를 이용하여 지수 형태로 변환하는 것이 가장 기본적이고 효율적인 풀이 방법입니다.",
