    "answer": 3,
    "explanation": "**[핵심 개념]**\n로그 방정식을 풀기 위해서는 로그의 정의를 이용하여 지수 형태로 변환해야 합니다.\n$\\log_a b = c$는 $a^c = b$와 동치입니다.\n또한 로그의 진수는 항상 양수여야 한다는 조건(정의역)을 확인해야 합니다.\n\n**[풀이]**\n\n주어진 방정식: $\\log_2(x-3)=3$\n\n**Step 1: 로그를 지수 형태로 변환**\n로그의 정의에 의해:\n$$\\log_2(x-3)=3 \\Leftrightarrow 2^3 = x-3$$\n\n**Step 2: 지수 계산**\n$$2^3 = 8$$\n따라서:\n$$8 = x-3$$\n\n**Step 3: x 구하기**\n$$x = 8 + 3 = 11$$\n\n**Step 4: 정의역 확인**\n$x=11$일 때, 진수는 $x-3 = 11-3 = 8 > 0$ ✓\n정의역 조건을 만족합니다.\n\n**[정답 확인]**\n$x=11$을 원래 식에 대입하면: $\\log_2(11-3) = \\log_2 8 = \\log_2 2^3 = 3$ ✓\n\n**[오답 분석]**\n- **① 9**: $\\log_2(9-3) = \\log_2 6 \\neq 3$ (틀림)\n- **② 16**: $\\log_2(16-3) = \\log_2 13 \\neq 3$ (틀림)\n- **③ 1**: $\\log_2(1-3) = \\log_2(-2)$ (진수가 음수로 정의역 위반)\n- **⑤ 8**: $\\log_2(8-3) = \\log_2 5 \\neq 3$ (틀림)\n\n**[핵심 포인트]**\n- 로그 방정식은 로그의 정의 $\\log_a b = c \\Leftrightarrow a^c = b$를 이용하여 지수 형태로 변환한다.\n- 풀이 후 항상 진수 > 0 조건을 확인하여 정의역을 만족하는지 검증해야 한다.",
