    "answer": 1,
    "explanation": "**[핵심 개념]**\n로그 방정식을 풀기 위해서는 로그의 정의를 이용하여 지수 형태로 변환해야 합니다.\n- 로그의 정의: $\\log_a b = c$ ⟺ $a^c = b$ (단, $a > 0, a \\neq 1, b > 0$)\n- 이 문제에서는 $\\log_2(x-4) = 5$를 지수 형태로 바꾸어 $x$를 구합니다.\n\n**[풀이]**\n\n**1단계: 로그 방정식을 지수 형태로 변환**\n\n$\\log_2(x-4) = 5$의 정의에 따라:\n$$2^5 = x - 4$$\n\n**2단계: 지수 계산**\n\n$$2^5 = 32$$\n\n따라서:\n$$32 = x - 4$$\n\n**3단계: $x$ 구하기**\n\n$$x = 32 + 4 = 36$$\n\n**[정답 확인]**\n$x = 36$을 원래 식에 대입하면: $\\log_2(36-4) = \\log_2 32 = \\log_2 2^5 = 5$ ✓\n\n**[오답 분석]**\n- **28**: $2^5 = 32 = x - 4$에서 $x = 32 - 4 = 28$로 계산한 오류 (부호 반대)\n- **39**: $2^5 = 32$를 $2^5 = 35$로 잘못 계산한 경우\n- **41**: $2^5 = 32 + 9 = 41$로 불필요한 덧셈을 추가한 경우\n- **40**: $2^5 = 36$으로 잘못 계산하여 $x = 40$이 된 경우\n\n**[핵심 포인트]**\n$\\log_a b = c$ 형태는 반드시 $a^c = b$로 변환하여 풀기. 로그 함수는 정의역 $x - 4 > 0$, 즉 $x > 4$를 만족하는지 확인 필요.",
