    "explanation": "**[핵심 개념]**\n로그 방정식을 풀기 위해서는 로그의 정의를 이용합니다. $\\log_a b = c$는 $a^c = b$와 동치입니다. \n또한 로그의 진수는 항상 양수여야 하므로 ($b > 0$), 구한 해가 정의역을 만족하는지 확인해야 합니다.\n\n**[풀이]**\n\n주어진 방정식: $\\log_2(x-5) = 2$\n\n**Step 1: 로그의 정의를 이용하여 지수 형태로 변환**\n\n$\\log_2(x-5) = 2$는 다음과 같이 쓸 수 있습니다:\n$$2^2 = x - 5$$\n\n**Step 2: 지수 계산**\n\n$$4 = x - 5$$\n\n**Step 3: x 구하기**\n\n$$x = 4 + 5 = 9$$\n\n**Step 4: 정의역 확인**\n\n로그의 진수는 양수여야 하므로 $x - 5 > 0$, 즉 $x > 5$이어야 합니다.\n$x = 9$일 때, $9 - 5 = 4 > 0$ ✓ (정의역 만족)\n\n**[정답 확인]**\n$x = 9$를 원래 식에 대입하면 $\\log_2(9-5) = \\log_2 4 = \\log_2 2^2 = 2$ ✓\n\n**[오답 분석]**\n\n- **② 1**: $1 - 5 = -4 < 0$이므로 로그의 진수가 음수가 되어 정의역을 만족하지 않습니다.\n- **③ 21**: $\\log_2(21-5) = \\log_2 16 = \\log_2 2^4 = 4 \\neq 2$\n- **④ 7**: $\\log_2(7-5) = \\log_2 2 = 1 \\neq 2$\n- **⑤ 4**: $4 - 5 = -1 < 0$이므로 로그의 진수가 음수가 되어 정의역을 만족하지 않습니다.\n\n**[핵심 포인트]**\n로그 방정식은 $\\log_a b = c \\Leftrightarrow a^c = b$ 형태로 변환하여 푸는 것이 기본입니다.\n항상 구한 해가 로그의 정의역(진수 > 0)을 만족하는지 검증하는 습관을 들이세요.",
