    "answer": 3,
    "explanation": "**[핵심 개념]**\n로그의 정의를 이용하여 지수 형태로 변환하는 것이 핵심입니다.\n로그 방정식 $\\log_a(b) = c$는 $a^c = b$로 변환됩니다.\n이를 통해 지수 방정식을 풀고, 로그의 진수 조건(진수 > 0)을 확인해야 합니다.\n\n**[풀이]**\n\n주어진 방정식: $\\log_2(x-6)=4$\n\n**1단계: 로그를 지수 형태로 변환**\n로그의 정의에 의해:\n$$\\log_2(x-6)=4 \\Leftrightarrow 2^4 = x-6$$\n\n**2단계: 지수 계산**\n$$2^4 = 16$$\n따라서:\n$$16 = x - 6$$\n\n**3단계: x에 대해 풀기**\n$$x = 16 + 6 = 22$$\n\n**4단계: 진수 조건 확인**\n로그의 진수는 양수여야 하므로 $x - 6 > 0$, 즉 $x > 6$이어야 합니다.\n$x = 22$일 때, $22 - 6 = 16 > 0$ ✓\n\n따라서 $x = 22$\n\n**[정답 확인]**\n$\\log_2(22-6) = \\log_2(16) = \\log_2(2^4) = 4$ ✓\n\n**[오답 분석]**\n- **27**: $2^4 = 16$이므로 $x - 6 = 16$에서 나오는 답이 아닙니다. ($27-6=21 \\neq 16$)\n- **30**: $x - 6 = 24$일 때의 답으로, $2^4 \\neq 24$입니다.\n- **20**: $x - 6 = 14$일 때인데, $2^4 = 16 \\neq 14$입니다.\n- **32**: 혹시 $2^5 = 32$와 혼동하여 $\\log_2(x-6)=5$로 잘못 푼 경우입니다.\n\n**[핵심 포인트]**\n$\\log_a(b) = c \\Leftrightarrow a^c = b$ 변환을 정확히 적용하고, 계산 후 진수 조건 $x - 6 > 0$을 확인하는 것이 중요합니다.",
