    "choices": [
      "8",
      "12",
      "14",
      "4",
      "7"
    ],
    "answer": 3,
    "explanation": "**[핵심 개념]**\n로그의 성질 중 $\\log_a b + \\log_a c = \\log_a(bc)$를 이용하여 좌변을 하나의 로그로 통합합니다. 그 후 양변의 로그를 제거하고 얻은 방정식을 풀되, 로그의 정의역(진수 > 0)을 만족하는 해만 채택해야 합니다.\n\n**[풀이]**\n\n**Step 1: 로그의 덧셈 공식 적용**\n\n좌변을 정리하면:\n$$\\log_2 x + \\log_2(x-2) = \\log_2[x(x-2)]$$\n\n따라서 주어진 식은:\n$$\\log_2[x(x-2)] = \\log_2 8$$\n\n**Step 2: 로그 제거**\n\n양변의 로그 기저가 같으므로, 로그를 제거하면:\n$$x(x-2) = 8$$\n\n**Step 3: 이차방정식 풀이**\n\n전개하면:\n$$x^2 - 2x = 8$$\n$$x^2 - 2x - 8 = 0$$\n\n인수분해:\n$$(x-4)(x+2) = 0$$\n\n따라서 $x = 4$ 또는 $x = -2$\n\n**Step 4: 정의역 확인**\n\n로그 함수의 정의역: 진수 > 0\n- $\\log_2 x$가 정의되려면 $x > 0$\n- $\\log_2(x-2)$가 정의되려면 $x - 2 > 0$, 즉 $x > 2$\n\n$x = 4$: $x > 2$를 만족 ✓\n$x = -2$: $x > 2$를 만족하지 않음 ✗\n\n**따라서 $x = 4$**\n\n**[정답 확인]**\n\n$x = 4$일 때: $\\log_2 4 + \\log_2 2 = 2 + 1 = 3 = \\log_2 8$ ✓\n\n**[오답 분석]**\n\n- **① 8**: $\\log_2 8 + \\log_2 6 = 3 + \\log_2 6 \\neq 3$ (계산 오류)\n- **② 12**: $\\log_2 12 + \\log_2 10 = \\log_2 120 \\neq 8$ (너무 큼)\n- **③ 14**: $\\log_2 14 + \\log_2 12 = \\log_2 168 \\neq 8$ (너무 큼)\n- **⑤ 7**: $\\log_2 7 + \\log_2 5 = \\log_2 35 \\neq 8$ (계산 불일치)\n\n**[핵심 포인트]**\n\n1. **로그 덧셈 공식**: $\\log_a b + \\log_a c = \\log_a(bc)$를 이용하여 한 개의 로그로 통합하는 것이 핵심\n2. **정의역 확인 필수**: 이차방정식의 모든 해가 원래 방정식의 해가 되는 것은 아니며, 반드시 진수 조건($x > 2$)을 확인해야 함",
