    "explanation": "**[핵심 개념]**\n로그의 성질 중 $\\log_a M + \\log_a N = \\log_a(MN)$을 이용하여 로그 방정식을 정리할 수 있습니다. 또한 로그 함수는 정의역이 양수로 제한되므로, 풀이 후 얻은 해가 정의역을 만족하는지 반드시 확인해야 합니다.\n\n**[풀이]**\n\n$\\log_2 x + \\log_2(x-2) = \\log_2 3$\n\n**1단계: 좌변의 로그를 합친다**\n로그의 성질 $\\log_a M + \\log_a N = \\log_a(MN)$을 적용하면:\n$$\\log_2[x(x-2)] = \\log_2 3$$\n\n**2단계: 로그를 제거한다**\n양변의 로그 밑이 같으므로 진수를 같다고 놓으면:\n$$x(x-2) = 3$$\n\n**3단계: 이차방정식으로 정리한다**\n$$x^2 - 2x = 3$$\n$$x^2 - 2x - 3 = 0$$\n\n**4단계: 인수분해로 풀이한다**\n$$(x-3)(x+1) = 0$$\n$$x = 3 \\text{ 또는 } x = -1$$\n\n**5단계: 정의역 확인**\n로그 함수의 정의역은 양수이므로:\n- $x > 0$이고\n- $x - 2 > 0$ (즉, $x > 2$)이어야 함\n\n따라서 $x > 2$를 만족하는 해는 $x = 3$뿐입니다.\n($x = -1$은 $x > 2$를 만족하지 않으므로 버림)\n\n**[정답 확인]**\n$x = 3$을 원래 식에 대입하면: $\\log_2 3 + \\log_2 1 = \\log_2 3 + 0 = \\log_2 3$ ✓\n\n**[오답 분석]**\n- **① 4**: $\\log_2 4 + \\log_2 2 = 2 + 1 = 3 \\neq \\log_2 3$ (계산 오류)\n- **② -7**: 정의역 조건 $x > 2$를 만족하지 않음 (음수)\n- **④ 13**: $\\log_2 13 + \\log_2 11 \\neq \\log_2 3$ (부정확한 계산)\n- **⑤ 6**: $\\log_2 6 + \\log_2 4 = \\log_2 24 \\neq \\log_2 3$ (계산 오류)\n\n**[핵심 포인트]**\n로그 방정식을 풀 때 이차방정식의 모든 해가 유효한 것은 아닙니다. 반드시 **로그의 정의역(모든 인수가 양수)**을 만족하는지 확인하는 검증 단계가 필수적입니다.",
