    "explanation": "**[핵심 개념]**\n로그의 성질 중 $\\log_a b + \\log_a c = \\log_a(bc)$를 이용하여 좌변을 정리합니다. 또한 로그 방정식을 풀 때는 정의역을 반드시 확인해야 합니다. $\\log_2 x$가 정의되려면 $x > 0$이고, $\\log_2(x-2)$가 정의되려면 $x > 2$이어야 합니다.\n\n**[풀이]**\n\n**1단계: 로그의 합을 곱으로 변환**\n$$\\log_2 x + \\log_2(x-2) = \\log_2[x(x-2)]$$\n\n따라서 주어진 방정식은:\n$$\\log_2[x(x-2)] = \\log_2 15$$\n\n**2단계: 로그를 제거하여 방정식 정리**\n밑이 같으므로 진수끼리 같습니다:\n$$x(x-2) = 15$$\n\n**3단계: 이차방정식 풀이**\n$$x^2 - 2x = 15$$\n$$x^2 - 2x - 15 = 0$$\n\n인수분해하면:\n$$(x-5)(x+3) = 0$$\n\n따라서 $x = 5$ 또는 $x = -3$\n\n**4단계: 정의역 확인**\n- $\\log_2 x$가 정의되려면: $x > 0$\n- $\\log_2(x-2)$가 정의되려면: $x > 2$\n\n따라서 $x > 2$를 만족해야 합니다.\n\n$x = -3$은 $x > 2$를 만족하지 않으므로 버립니다.\n$x = 5$는 $5 > 2$를 만족하므로 유효한 해입니다.\n\n**[정답 확인]**\n$x = 5$를 원래 식에 대입: $\\log_2 5 + \\log_2 3 = \\log_2 15$ ✓\n\n**[오답 분석]**\n- **0**: 정의역 위반 ($\\log_2 0$은 정의되지 않음)\n- **2**: $\\log_2(2-2) = \\log_2 0$이므로 정의되지 않음\n- **7**: $7(7-2) = 35 \\neq 15$\n- **17**: $17(17-2) = 255 \\neq 15$\n\n**[핵심 포인트]**\n로그 방정식을 풀 때 이차방정식의 해를 구한 후 반드시 **정의역 조건을 확인**해야 합니다. 이 문제에서는 $x > 2$ 조건에 의해 $x = -3$을 제외하고 $x = 5$만이 답입니다.",
