    "answer": 4,
    "explanation": "**[핵심 개념]**\n로그의 덧셈 공식: $\\log_a b + \\log_a c = \\log_a(bc)$\n로그 방정식을 풀 때는 밑이 같으면 진수끼리 같다는 성질을 이용합니다.\n또한 로그의 정의역을 만족하는지 반드시 확인해야 합니다. $\\log_a x$에서 $x > 0$이어야 합니다.\n\n**[풀이]**\n\n**Step 1: 로그의 덧셈 공식 적용**\n\n$$\\log_2 x + \\log_2(x-2) = \\log_2 35$$\n\n좌변의 두 로그를 합치면:\n$$\\log_2[x(x-2)] = \\log_2 35$$\n\n**Step 2: 밑이 같으므로 진수를 같다고 놓기**\n\n$$x(x-2) = 35$$\n\n**Step 3: 이차방정식 풀기**\n\n$$x^2 - 2x = 35$$\n$$x^2 - 2x - 35 = 0$$\n\n인수분해하면:\n$$(x-7)(x+5) = 0$$\n\n따라서 $x = 7$ 또는 $x = -5$\n\n**Step 4: 정의역 확인**\n\n원래 방정식에서 $\\log_2 x$와 $\\log_2(x-2)$가 정의되려면:\n- $x > 0$ 이어야 하고\n- $x - 2 > 0$, 즉 $x > 2$ 이어야 합니다.\n\n따라서 $x > 2$를 만족해야 합니다.\n\n$x = 7$: $7 > 2$ ✓ (만족)\n$x = -5$: $-5 > 2$ ✗ (불만족)\n\n따라서 **$x = 7$**\n\n**[정답 확인]**\n$x = 7$을 원래 식에 대입하면: $\\log_2 7 + \\log_2 5 = \\log_2 35$ ✓\n\n**[오답 분석]**\n- **① 11**: 계산 실수로 선택할 수 있지만, $x^2 - 2x - 35 = 0$의 해가 아닙니다.\n- **② -3**: $x^2 - 2x - 35 = 0$의 해가 아니며, 정의역도 만족하지 않습니다.\n- **③ 6**: 계산 실수로 선택할 수 있지만, $6^2 - 2(6) - 35 = 36 - 12 - 35 = -11 \\neq 0$\n- **④ 2**: $2 > 2$를 만족하지 않으므로 $\\log_2(x-2)$가 정의되지 않습니다.\n- **⑤ 7**: 올바른 답 ✓\n\n**[핵심 포인트]**\n로그 방정식을 풀 때 이차방정식의 모든 해가 원래 방정식의 해가 되는 것은 아닙니다. 반드시 **로그의 정의역(진수 > 0)을 확인**하여 불필요한 해를 제외해야 합니다.",
