    "answer": 4,
    "explanation": "**[핵심 개념]**\n지수함수 $y=a^x$ (단, $a>0, a \\neq 1$)의 그래프와 직선의 교점을 구하는 문제입니다. 두 함수의 그래프가 만나는 점에서는 $y$값이 같으므로, 주어진 두 식을 같다고 놓고 $x$에 대한 방정식을 풀어야 합니다. 지수방정식을 풀기 위해 밑을 같게 만드는 과정이 중요합니다.\n\n**[풀이]**\n\n$y=2^{x-3}+5$의 그래프가 직선 $y=9$와 만나므로, 교점에서 두 $y$값이 같습니다.\n\n$$2^{x-3}+5=9$$\n\n양변에서 5를 빼면:\n$$2^{x-3}=4$$\n\n우변을 2의 거듭제곱으로 나타내면:\n$$2^{x-3}=2^2$$\n\n밑이 같은 지수함수는 일대일 대응이므로 지수끼리 같습니다:\n$$x-3=2$$\n\n양변에 3을 더하면:\n$$x=5$$\n\n**[정답 확인]**\n$x=5$를 원래 식에 대입하면: $y=2^{5-3}+5=2^2+5=4+5=9$ ✓ 직선 $y=9$와 만나는 조건을 만족합니다.\n\n**[오답 분석]**\n- **① 11**: $2^{11-3}+5=2^8+5=256+5=261 \\neq 9$ (지수를 더한 경우)\n- **② 8**: $2^{8-3}+5=2^5+5=32+5=37 \\neq 9$ (계산 오류)\n- **③ 13**: $2^{13-3}+5=2^{10}+5=1024+5=1029 \\neq 9$ (큰 값으로 계산)\n- **④ 3**: $2^{3-3}+5=2^0+5=1+5=6 \\neq 9$ (지수 계산 오류)\n\n**[핵심 포인트]**\n지수방정식 $a^{x}=a^{n}$일 때는 $x=n$임을 이용하면 됩니다. 주어진 식을 정리하여 같은 밑을 가진 지수 형태로 만드는 것이 핵심입니다.",
