    "answer": 3,
    "explanation": "**[핵심 개념]**\n지수함수와 직선의 교점을 구하는 문제입니다. 두 함수가 만나는 점에서는 $y$값이 같으므로, 주어진 두 식을 같다고 놓고 $x$를 구합니다. 지수방정식을 풀기 위해 양변을 같은 밑의 거듭제곱으로 표현해야 합니다.\n\n**[풀이]**\n\n$y=3^{x-2}+4$의 그래프가 직선 $y=13$과 만나는 점에서 $y$값이 같으므로:\n\n$$3^{x-2}+4=13$$\n\n양변에서 4를 빼면:\n\n$$3^{x-2}=9$$\n\n우변 9를 3의 거듭제곱으로 나타내면:\n\n$$3^{x-2}=3^2$$\n\n밑이 같으면 지수도 같으므로:\n\n$$x-2=2$$\n\n따라서:\n\n$$x=4$$\n\n**[정답 확인]**\n$x=4$를 원래 식에 대입하면 $y=3^{4-2}+4=3^2+4=9+4=13$ ✓\n\n**[오답 분석]**\n- **10**: 지수 계산 실수 ($3^8=6561$이므로 맞지 않음)\n- **7**: $3^{7-2}=3^5=243$이므로 $243+4=247≠13$\n- **9**: $3^{9-2}=3^7=2187$이므로 $2187+4=2191≠13$\n- **12**: $3^{12-2}=3^{10}$은 매우 큰 수이므로 맞지 않음\n\n**[핵심 포인트]**\n지수방정식을 풀 때는 양변을 같은 밑으로 표현하여 지수끼리 같다고 놓는 것이 핵심입니다. 특히 우변의 작은 수를 주어진 밑의 거듭제곱으로 변환하는 과정이 중요합니다.",
