    "explanation": "**[핵심 개념]**\n지수함수 $y=a^x$ (단, $a>0, a≠1$)의 그래프와 직선의 교점을 구하는 문제입니다. 두 함수가 만나는 점에서는 $y$값이 같으므로, 주어진 $y$값을 지수함수 식에 대입하여 $x$를 구합니다. 지수방정식을 풀기 위해 양변을 같은 밑의 거듭제곱으로 표현합니다.\n\n**[풀이]**\n$y=2^{x-4}+7$의 그래프가 직선 $y=11$과 만나는 점에서 두 식의 $y$값이 같습니다.\n\n$$2^{x-4}+7=11$$\n\n양변에서 7을 빼면:\n$$2^{x-4}=11-7$$\n\n$$2^{x-4}=4$$\n\n우변을 2의 거듭제곱으로 표현합니다. $4=2^2$이므로:\n$$2^{x-4}=2^2$$\n\n밑이 같은 지수방정식에서 지수가 같아야 하므로:\n$$x-4=2$$\n\n$$x=6$$\n\n**[정답 확인]**\n$x=6$을 원래 식에 대입하면 $y=2^{6-4}+7=2^2+7=4+7=11$ ✓ 직선 $y=11$과 만나므로 정답입니다.\n\n**[오답 분석]**\n- ① $x=4$: $y=2^{4-4}+7=2^0+7=1+7=8≠11$\n- ② $x=8$: $y=2^{8-4}+7=2^4+7=16+7=23≠11$\n- ③ $x=14$: $y=2^{14-4}+7=2^{10}+7=1024+7=1031≠11$\n- ⑤ $x=-2$: $y=2^{-2-4}+7=2^{-6}+7=\\frac{1}{64}+7≈7.016≠11$\n\n**[핵심 포인트]**\n지수방정식 $a^f(x)=a^{g(x)}$에서는 밑이 같으면 지수도 반드시 같아야 한다는 성질을 이용합니다. 우변 4를 $2^2$로 변형하는 것이 가장 중요한 단계입니다.",
