    "explanation": "**[핵심 개념]**\n지수함수와 직선의 교점을 구하는 문제입니다. 두 함수가 만나는 점에서는 $y$값이 같으므로, 주어진 두 식을 같다고 놓고 $x$를 구합니다. 이때 지수방정식을 풀기 위해 지수의 성질을 이용하여 밑을 같게 만들어야 합니다.\n\n**[풀이]**\n\n**Step 1: 교점 조건 설정**\n$y=5^{x-2}+6$의 그래프가 직선 $y=31$과 만나므로:\n$$5^{x-2}+6=31$$\n\n**Step 2: 지수항 정리**\n양변에서 6을 빼면:\n$$5^{x-2}=31-6$$\n$$5^{x-2}=25$$\n\n**Step 3: 밑을 같게 만들기**\n$25=5^2$이므로:\n$$5^{x-2}=5^2$$\n\n**Step 4: 지수 비교**\n밑이 같은 지수함수는 일대일 대응이므로 지수를 비교하면:\n$$x-2=2$$\n$$x=4$$\n\n**[정답 확인]**\n$x=4$를 원래 함수에 대입하면: $y=5^{4-2}+6=5^2+6=25+6=31$ ✓\n\n**[오답 분석]**\n\n- **② -4**: $5^{-4-2}+6=5^{-6}+6 \\approx 6$ (31이 아님)\n- **③ 5**: $5^{5-2}+6=5^3+6=125+6=131$ (31이 아님)\n- **④ 14**: $5^{14-2}+6=5^{12}+6$ (매우 큰 수, 31이 아님)\n- **⑤ 12**: $5^{12-2}+6=5^{10}+6$ (매우 큰 수, 31이 아님)\n\n**[핵심 포인트]**\n지수방정식을 풀 때 $5^{x-2}=25=5^2$ 형태로 밑을 같게 만들면 지수를 직접 비교할 수 있습니다. 항상 양변이 같은 밑의 거듭제곱 형태가 되도록 정리하는 것이 핵심입니다.",
