    "explanation": "**[핵심 개념]**\n두 곡선의 교점을 구하기 위해 두 함수를 같다고 놓고 지수방정식을 풀어야 한다. 교점 $P$의 좌표를 $(x_0, y_0)$라 하면, $H$는 $x$축 위의 점 $(x_0, 0)$이고 $K$는 $y$축 위의 점 $(0, y_0)$이다. 직사각형 $OHPK$의 넓이는 $x_0 \\times y_0$이다.\n\n**[풀이]**\n\n**1단계: 교점 P의 x좌표 구하기**\n\n두 곡선의 교점에서:\n$$2^{x-1} = 2^{7-x}$$\n\n지수가 같으므로 지수끼리 같다:\n$$x - 1 = 7 - x$$\n\n$$2x = 8$$\n\n$$x = 4$$\n\n**2단계: 교점 P의 y좌표 구하기**\n\n$x = 4$를 $y = 2^{x-1}$에 대입:\n$$y = 2^{4-1} = 2^3 = 8$$\n\n검증: $y = 2^{7-x} = 2^{7-4} = 2^3 = 8$ ✓\n\n따라서 교점 $P(4, 8)$\n\n**3단계: 수선의 발 구하기**\n\n- $P$에서 $x$축에 내린 수선의 발: $H(4, 0)$\n- $P$에서 $y$축에 내린 수선의 발: $K(0, 8)$\n\n**4단계: 직사각형 OHPK의 넓이**\n\n원점 $O(0, 0)$, $H(4, 0)$, $P(4, 8)$, $K(0, 8)$로 이루어진 직사각형의 넓이:\n\n$$\\text{넓이} = |OH| \\times |OK| = 4 \\times 8 = 32$$\n\n**[정답 확인]**\n교점의 좌표가 $(4, 8)$이므로 직사각형의 넓이는 $4 \\times 8 = 32$이다.\n\n**[오답 분석]**\n- **35**: 계산 실수 또는 $x$좌표를 잘못 구한 경우\n- **25**: 교점의 좌표를 잘못 구하여 $5 \\times 5$로 계산한 경우\n- **19**: 직사각형의 넓이 대신 둘레를 구하거나 다른 도형의 넓이로 계산한 경우\n- **34**: 계산 실수 또는 근삿값으로 계산한 경우\n\n**[핵심 포인트]**\n지수방정식 $2^{x-1} = 2^{7-x}$에서 밑이 같으므로 지수끼리 같다는 조건을 사용하면 $x = 4$를 얻을 수 있다. 교점의 좌표가 구해지면 직사각형의 넓이는 단순히 가로 × 세로의 곱이다.",
