    "explanation": "**[핵심 개념]**\n두 곡선의 교점은 두 식이 같은 점이므로, 두 함수를 같다고 놓고 방정식을 세워 해를 구합니다. 지수 함수의 성질 $2^{x+1} = 2 \\cdot 2^x$를 이용하여 지수식을 정리할 수 있습니다.\n\n**[풀이]**\n\n교점 $P$에서 두 곡선의 $y$값이 같으므로:\n$$2^x + 1 = 2^{x+1} - 5$$\n\n$2^{x+1} = 2 \\cdot 2^x$로 정리하면:\n$$2^x + 1 = 2 \\cdot 2^x - 5$$\n\n양변을 정리합니다:\n$$2^x + 1 = 2 \\cdot 2^x - 5$$\n$$1 + 5 = 2 \\cdot 2^x - 2^x$$\n$$6 = 2^x$$\n\n따라서 $2^x = 6$입니다.\n\n이제 교점의 $y$좌표를 구하기 위해 첫 번째 곡선의 식에 $2^x = 6$을 대입합니다:\n$$y = 2^x + 1 = 6 + 1 = 7$$\n\n검증: 두 번째 곡선에서도 확인하면\n$$y = 2^{x+1} - 5 = 2 \\cdot 2^x - 5 = 2 \\cdot 6 - 5 = 12 - 5 = 7$$ ✓\n\n**[정답 확인]**\n$2^x = 6$일 때 두 곡선의 $y$값이 모두 7로 같으므로 교점의 $y$좌표는 7입니다.\n\n**[오답 분석]**\n- **0**: $2^x + 1 = 0$에서 $2^x = -1$인데 지수함수는 항상 양수이므로 불가능\n- **19**: 계산 오류 (예: $2^x = 18$로 잘못 계산한 경우)\n- **-2**: 음수값으로, $2^x + 1$은 항상 1보다 크므로 불가능\n- **4**: $2^x = 3$으로 잘못 계산한 경우 ($3 + 1 = 4$)\n\n**[핵심 포인트]**\n교점을 구할 때는 두 함수를 같다고 놓아 미지수의 값을 먼저 구하고, 이를 원래 함수식에 대입하여 좌표를 구하는 절차가 중요합니다. 지수함수의 성질 $a^{x+n} = a^n \\cdot a^x$를 적절히 활용하면 복잡한 식도 간단히 정리됩니다.",
