    "explanation": "**[핵심 개념]**\n두 곡선의 교점은 두 함수값이 같아지는 점입니다. 따라서 교점의 좌표를 구하려면 두 함수를 같다고 놓고 방정식을 풀어야 합니다. 지수함수의 성질 $3^{x+1} = 3 \\cdot 3^x$를 이용하면 지수방정식을 간단히 정리할 수 있습니다.\n\n**[풀이]**\n\n교점 $P$에서 두 곡선의 $y$값이 같으므로:\n$$3^x + 1 = 3^{x+1} - 5$$\n\n지수법칙을 적용하여 $3^{x+1} = 3 \\cdot 3^x$로 정리합니다:\n$$3^x + 1 = 3 \\cdot 3^x - 5$$\n\n$3^x$를 $t$로 치환하면 ($t > 0$):\n$$t + 1 = 3t - 5$$\n\n$t$에 대해 정리합니다:\n$$1 + 5 = 3t - t$$\n$$6 = 2t$$\n$$t = 3$$\n\n따라서 $3^x = 3$이므로 $x = 1$입니다.\n\n이제 교점의 $y$좌표를 구합니다. 첫 번째 곡선에 $x=1$을 대입:\n$$y = 3^1 + 1 = 3 + 1 = 4$$\n\n검증: 두 번째 곡선에 $x=1$을 대입하면\n$$y = 3^{1+1} - 5 = 3^2 - 5 = 9 - 5 = 4$$ ✓\n\n**[정답 확인]**\n두 곡선에서 $x=1$일 때 모두 $y=4$가 되므로 교점의 $y$좌표는 4입니다.\n\n**[오답 분석]**\n- ①번(7): 계산 오류로 $3^x$를 잘못 구한 경우\n- ②번(6): $t=2$로 잘못 계산하여 $3^x=2$로 푼 경우\n- ④번(-3): 음수를 선택하려는 오류 (지수함수는 항상 양수)\n- ⑤번(-5): 두 번째 식의 상수항만 답으로 착각한 경우\n\n**[핵심 포인트]**\n두 곡선의 교점을 구할 때는 두 함수를 같다고 놓는 것이 필수이며, 지수방정식에서는 치환을 통해 일차방정식으로 변환하여 푸는 것이 효과적입니다.",
