    "explanation": "**[핵심 개념]**\n역함수의 정의와 성질을 이용하는 문제입니다.\n- $f(x) = 2^{x-1}$일 때, 역함수 $g(x) = f^{-1}(x)$는 $f(g(x)) = x$를 만족합니다.\n- 역함수를 구하려면 $y = f(x)$에서 $x$와 $y$를 바꾼 후 $y$에 대해 정리합니다.\n- 지수함수 $y = a^x$의 역함수는 로그함수 $y = \\log_a x$입니다.\n\n**[풀이]**\n\n**Step 1: 역함수 $g(x)$ 구하기**\n\n$f(x) = 2^{x-1}$의 역함수를 구합니다.\n\n$y = 2^{x-1}$에서 $x$와 $y$를 바꾸면:\n$$x = 2^{y-1}$$\n\n양변에 로그를 취합니다:\n$$\\log_2 x = y - 1$$\n\n따라서:\n$$y = \\log_2 x + 1$$\n\n즉, $g(x) = \\log_2 x + 1$\n\n**Step 2: $g(8)$ 계산**\n\n$$g(8) = \\log_2 8 + 1 = \\log_2 2^3 + 1 = 3 + 1 = 4$$\n\n**Step 3: $f(4)$ 계산**\n\n$$f(4) = 2^{4-1} = 2^3 = 8$$\n\n**Step 4: $g(8) + f(4)$ 계산**\n\n$$g(8) + f(4) = 4 + 8 = 12$$\n\n**[정답 확인]**\n$g(8) = 4$, $f(4) = 8$이므로 $g(8) + f(4) = 12$입니다. 검증: $f(g(8)) = f(4) = 8$ ✓\n\n**[오답 분석]**\n- **9**: $g(8) + f(4)$를 계산할 때 $f(4) = 4$로 잘못 계산한 경우\n- **5**: $f(4) = 2$로 오류를 범한 경우\n- **17**: $f(4) = 13$으로 잘못 계산하거나 계산 실수\n- **21**: 역함수나 함숫값을 완전히 잘못 계산한 경우\n\n**[핵심 포인트]**\n1. 지수함수 $y = a^x$의 역함수는 로그함수 $y = \\log_a x$임을 반드시 기억\n2. 평행이동된 함수의 역함수를 구할 때는 먼저 역함수를 구한 후 평행이동을 적용하는 순서에 주의",
