    "explanation": "**[핵심 개념]**\n역함수의 정의와 성질을 이용하여 문제를 해결합니다.\n- 함수 $f$의 역함수 $g = f^{-1}$일 때, $g(a) = b$ ⟺ $f(b) = a$\n- 지수함수 $f(x) = a^x$ (단, $a > 0, a \\neq 1$)의 역함수는 로그함수 $f^{-1}(x) = \\log_a x$\n\n**[풀이]**\n\n**1단계: $f(x) = 3^{x-1}$의 역함수 $g(x)$ 구하기**\n\n$y = 3^{x-1}$에서 $x$와 $y$를 바꾸면:\n$$x = 3^{y-1}$$\n\n양변에 로그를 취합니다:\n$$\\log_3 x = y - 1$$\n$$y = \\log_3 x + 1$$\n\n따라서 $g(x) = \\log_3 x + 1$\n\n**2단계: $g(9)$ 계산하기**\n\n$$g(9) = \\log_3 9 + 1$$\n\n$9 = 3^2$이므로:\n$$g(9) = \\log_3 3^2 + 1 = 2 + 1 = 3$$\n\n**3단계: $f(3)$ 계산하기**\n\n$$f(3) = 3^{3-1} = 3^2 = 9$$\n\n**4단계: 최종 답 계산**\n\n$$g(9) + f(3) = 3 + 9 = 12$$\n\n**[정답 확인]**\n$g(9) = 3$, $f(3) = 9$이므로 합은 12이며, 정답 ③과 일치합니다.\n\n**[오답 분석]**\n- ① 21: $g(9) + f(3)$을 잘못 계산하거나 다른 값들을 더한 경우\n- ② 11: $g(9) = 2$로 잘못 계산한 경우 (로그 계산 실수)\n- ④ 16: 계산 과정에서 산술 오류\n- ⑤ 3: $g(9)$의 값만 답한 경우\n\n**[핵심 포인트]**\n역함수 $g = f^{-1}$일 때는 정의에 따라 $g(a) = b$ ⟺ $f(b) = a$를 직접 이용할 수도 있습니다. 즉, $g(9) = b$라 하면 $f(b) = 9$이므로 $3^{b-1} = 9 = 3^2$에서 $b = 3$으로 더 빠르게 구할 수 있습니다.",
