    "explanation": "**[핵심 개념]**\n로그함수의 정의역을 구하기 위해서는 로그의 진수가 항상 양수여야 한다는 조건을 사용합니다. $\\log_a(u)$가 정의되려면 $u > 0$이어야 합니다. 여러 로그가 곱해진 형태일 때는 각 진수가 모두 양수 조건을 동시에 만족해야 합니다.\n\n**[풀이]**\n\n함수 $f(x)=\\log_{2}(x-2)+\\log_{2}(5-x)$의 정의역을 구하기 위해 각 로그의 진수가 양수여야 합니다.\n\n**Step 1: 첫 번째 로그의 조건**\n$$\\log_2(x-2) \\text{가 정의되려면 } x-2 > 0$$\n$$\\therefore x > 2$$\n\n**Step 2: 두 번째 로그의 조건**\n$$\\log_2(5-x) \\text{가 정의되려면 } 5-x > 0$$\n$$\\therefore x < 5$$\n\n**Step 3: 정의역 결정**\n두 조건을 모두 만족해야 하므로:\n$$2 < x < 5$$\n\n**Step 4: 정의역에 속하는 정수 찾기**\n$2 < x < 5$를 만족하는 정수 $x$는:\n- $x = 3$\n- $x = 4$\n\n따라서 정의역에 속하는 정수는 **2개**입니다.\n\n**[정답 확인]**\n$2 < x < 5$ 범위의 정수는 3과 4로 정확히 2개이므로 정답은 ④번입니다.\n\n**[오답 분석]**\n- ① (11): 계산 과정에서 부등호 방향을 잘못 이해하거나 범위를 잘못 설정한 경우\n- ② (14): 정의역을 잘못 구하거나 범위를 초과하여 센 경우\n- ③ (3): 정의역의 경계값인 2나 5를 포함시킨 경우 (경계값은 부등호가 등호가 아니므로 제외)\n- ⑤ (25): 정의역을 전혀 고려하지 않고 임의로 선택한 경우\n\n**[핵심 포인트]**\n로그함수의 정의역은 진수가 **양수**이어야 하며, 경계값(부등호의 등호 조건)은 포함되지 않습니다. 여러 로그가 있을 때는 각 진수의 조건을 모두 교집합으로 취해야 합니다.",
