    "problem": "곡선 $y=\\log_{2}(x-2)$ 위의 점 $A,B$의 $y$좌표가 각각 1, 3이다. $A,B$를 마주 보는 꼭짓점으로 하는 축에 평행한 직사각형의 넓이는?",
