    "problem": "$f(x)=2^{x-1}$ 위의 점 $A(4,8)$를 직선 $y=x$에 대칭시킨 점을 $B$라 한다. 원점 $O$에 대해 삼각형 $OAB$의 넓이의 2배는?",
