    "explanation": "**[핵심 개념]**\n두 점이 직선 $y=x$에 대해 대칭일 때, 점 $(a,b)$의 대칭점은 $(b,a)$입니다. 즉, $x$좌표와 $y$좌표가 서로 바뀝니다. 두 점 사이의 거리는 거리 공식 $\\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}$로 구하며, 거리의 제곱은 $(\\Delta x)^2+(\\Delta y)^2$입니다.\n\n**[풀이]**\n\n**1단계: 점 A 확인**\n문제에서 $A=(2,4)$이고 이 점이 $y=2^x$ 위에 있다고 했으므로, 검증하면:\n$$y=2^2=4 \\text{ ✓}$$\n\n**2단계: 점 B 구하기**\n점 $A=(2,4)$를 직선 $y=x$에 대해 대칭이동한 점 $B$는 좌표를 바꾼 것입니다.\n$$B=(4,2)$$\n\n**3단계: 선분 AB의 길이의 제곱 계산**\n두 점 $A=(2,4)$와 $B=(4,2)$ 사이의 거리의 제곱은:\n$$|AB|^2 = (4-2)^2 + (2-4)^2$$\n$$= 2^2 + (-2)^2$$\n$$= 4 + 4$$\n$$= 8$$\n\n**[정답 확인]**\n점 $A=(2,4)$를 직선 $y=x$에 대해 대칭이동하면 $B=(4,2)$이고, 두 점 사이의 거리의 제곱은 $(4-2)^2+(2-4)^2=8$입니다.\n\n**[오답 분석]**\n- **①번 13**: $(2-4)^2+(4-2)^2=4+4=8$인데 계산 오류로 더한 경우\n- **③번 12**: 거리의 제곱을 구하지 않고 거리 공식에 오류를 더한 경우\n- **④번 11**: 계산 과정에서 산술 오류\n- **⑤번 -5**: 거리의 제곱이 음수가 될 수 없으므로 명백히 오답\n\n**[핵심 포인트]**\n직선 $y=x$에 대한 대칭점은 좌표를 단순히 바꾸면 되고, 거리의 제곱을 구할 때는 각 성분의 차이를 제곱하여 더하면 됩니다.",
