    "explanation": "**[핵심 개념]**\n지수함수 위의 점의 좌표를 구하기 위해 함수값으로부터 $x$값을 역으로 계산하는 방법, 그리고 사다리꼴의 넓이 공식을 활용합니다.\n- 지수방정식: $2^{x-1} = y$일 때, $x-1 = \\log_2 y$\n- 사다리꼴의 넓이: $\\frac{1}{2}(a+b) \\times h$ (평행한 두 변이 $a, b$이고 높이가 $h$)\n\n**[풀이]**\n\n**1단계: 점 A의 좌표 구하기**\n\n점 $A$의 함수값이 $4$이므로:\n$$2^{x-1} = 4 = 2^2$$\n$$x - 1 = 2$$\n$$x = 3$$\n\n따라서 $A(3, 4)$\n\n**2단계: 점 B의 좌표 구하기**\n\n점 $B$의 함수값이 $16$이므로:\n$$2^{x-1} = 16 = 2^4$$\n$$x - 1 = 4$$\n$$x = 5$$\n\n따라서 $B(5, 16)$\n\n**3단계: 점 H, K의 좌표 구하기**\n\n$A$에서 $x$축에 내린 수선의 발: $H(3, 0)$\n\n$B$에서 $x$축에 내린 수선의 발: $K(5, 0)$\n\n**4단계: 사다리꼴 ABKH의 넓이 계산**\n\n사다리꼴 $ABKH$는:\n- 평행한 두 변: $AH = 4$ (수직선), $BK = 16$ (수직선)\n- 높이: $HK = 5 - 3 = 2$ (수평거리)\n\n사다리꼴의 넓이:\n$$\\text{넓이} = \\frac{1}{2}(AH + BK) \\times HK$$\n$$= \\frac{1}{2}(4 + 16) \\times 2$$\n$$= \\frac{1}{2} \\times 20 \\times 2$$\n$$= 20$$\n\n**[정답 확인]**\n\n지수방정식을 올바르게 풀어 두 점의 좌표를 구하고, 사다리꼴 넓이 공식을 정확히 적용하면 답은 20입니다.\n\n**[오답 분석]**\n\n- **39**: 두 평행변을 더한 후 높이를 곱하고 2로 나누지 않은 경우 $(4+16) \\times 2 = 40$ 근처에서의 계산 오류\n- **29**: 높이를 잘못 계산하거나 불필요한 값을 더한 경우\n- **15**: 사다리꼴의 넓이를 계산할 때 평행변 중 하나를 누락하거나 높이를 오인한 경우\n- **25**: $\\frac{1}{2}(4+16) \\times 2 = 20$에서 계산 실수 또는 한 변의 길이를 잘못 적용한 경우\n\n**[핵심 포인트]**\n\n1. 지수함수 $2^{x-1} = y$에서 $x$값을 구할 때는 양변의 로그를 취하거나 지수를 같은 밑으로 맞춰 비교합니다.\n2. 사다리꼴의 넓이는 평행한 두 변(여기서는 수직인 선분들)의 길이와 그 사이의 거리(높이)를 정확히 파악하는 것이 중요합니다.",
