    "explanation": "**[핵심 개념]**\n지수함수 위의 점의 좌표를 구하기 위해 함수값으로부터 x값을 역으로 계산하는 방법, 그리고 사다리꼴의 넓이 공식을 사용해야 합니다. 사다리꼴의 넓이는 $\\frac{1}{2}(b_1 + b_2) \\times h$ (두 밑변의 합에 높이를 곱하고 2로 나눔)입니다.\n\n**[풀이]**\n\n**1단계: 점 A의 좌표 구하기**\n\n점 A의 함수값이 3이므로:\n$$3^{x_A - 2} = 3$$\n$$3^{x_A - 2} = 3^1$$\n$$x_A - 2 = 1$$\n$$x_A = 3$$\n\n따라서 $A(3, 3)$\n\n**2단계: 점 B의 좌표 구하기**\n\n점 B의 함수값이 27이므로:\n$$3^{x_B - 2} = 27$$\n$$3^{x_B - 2} = 3^3$$\n$$x_B - 2 = 3$$\n$$x_B = 5$$\n\n따라서 $B(5, 27)$\n\n**3단계: 수선의 발 H, K의 좌표 구하기**\n\n점 A에서 x축에 내린 수선의 발: $H(3, 0)$\n\n점 B에서 x축에 내린 수선의 발: $K(5, 0)$\n\n**4단계: 사다리꼴의 형태 파악**\n\n사다리꼴 ABKH의 꼭짓점:\n- $A(3, 3)$\n- $B(5, 27)$\n- $K(5, 0)$\n- $H(3, 0)$\n\n이 사다리꼴은:\n- 밑변 HK: x축 위의 선분으로 길이 $= 5 - 3 = 2$\n- 다른 밑변 AB: 평행하지 않음 (수직이 아닌 선분)\n- 두 다리: AH와 BK는 모두 수직선\n\n실제로 AH와 BK가 평행하므로(모두 수직), 이는 직각사다리꼴입니다.\n- 한 다리 AH의 길이 $= 3$\n- 다른 다리 BK의 길이 $= 27$\n- 높이(두 다리 사이의 거리) $= 2$\n\n**5단계: 사다리꼴의 넓이 계산**\n\n$$\\text{넓이} = \\frac{1}{2}(AH + BK) \\times \\text{높이}$$\n$$= \\frac{1}{2}(3 + 27) \\times 2$$\n$$= \\frac{1}{2} \\times 30 \\times 2$$\n$$= 30$$\n\n**[정답 확인]**\n두 평행한 변(수직선 AH와 BK)이 각각 길이 3과 27이고, 이들 사이의 거리가 2이므로 사다리꼴 넓이 공식을 적용하면 30이 됩니다.\n\n**[오답 분석]**\n- **31**: 계산 실수 (높이를 2.1로 계산하거나 30에 1을 더함)\n- **49**: 직사각형처럼 계산하거나 높이를 잘못 적용 ($25 \\times 2 - 1$)\n- **33**: 넓이 공식에서 $\\frac{1}{2}$를 빼먹고 계산\n- **29**: 한쪽 변의 길이를 1씩 줄여서 계산하는 실수\n\n**[핵심 포인트]**\n지수함수 위의 점을 구할 때는 주어진 함수값을 이용해 지수 방정식을 풀어야 하며, 사다리꼴 넓이는 두 평행한 변의 길이와 그들 사이의 수직거리를 정확히 파악해야 합니다.",
