    "explanation": "**[핵심 개념]**\n지수함수와 로그함수는 역함수 관계이므로 $y=a^x$와 $y=\\log_a x$는 직선 $y=x$에 대해 대칭입니다. 또한 $y=2^{x-2}$와 $y=\\log_2(x-2)$는 직선 $y=x$에 대해 대칭인 함수들입니다. 주어진 직선 $y=2$와의 교점을 구하고, 두 점 사이의 거리는 거리 공식 $\\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}$을 이용합니다.\n\n**[풀이]**\n\n**Step 1: 점 A의 좌표 구하기**\n\n$y=2^{x-2}$와 $y=2$의 교점 A를 구합니다.\n\n$$2^{x-2}=2$$\n\n$$2^{x-2}=2^1$$\n\n$$x-2=1$$\n\n$$x=3$$\n\n따라서 $A(3, 2)$입니다.\n\n**Step 2: 점 B의 좌표 구하기**\n\n$y=\\log_2(x-2)$와 $y=2$의 교점 B를 구합니다.\n\n$$\\log_2(x-2)=2$$\n\n$$x-2=2^2$$\n\n$$x-2=4$$\n\n$$x=6$$\n\n따라서 $B(6, 2)$입니다.\n\n**Step 3: 두 점 A, B 사이의 거리 계산**\n\n두 점의 $y$좌표가 모두 2로 같으므로, 거리는:\n\n$$|AB|=\\sqrt{(6-3)^2+(2-2)^2}=\\sqrt{9+0}=\\sqrt{9}=3$$\n\n**Step 4: 거리에서 1을 뺀 값**\n\n$$|AB|-1=3-1=2$$\n\n**[정답 확인]**\n점 A와 B의 거리는 3이고, 여기서 1을 빼면 2가 되므로 정답은 ②번입니다.\n\n**[오답 분석]**\n- ①번(25): 거리의 제곱값 9에 착각하거나 계산 오류\n- ③번(14): 거리 계산을 잘못하여 과도하게 큰 값을 얻은 경우\n- ④번(6): 거리를 $3\\times 2=6$으로 잘못 계산한 경우\n- ⑤번(-5): 음수값이 나오는 것은 거리 개념을 잘못 이해한 경우\n\n**[핵심 포인트]**\n두 함수가 같은 $y$값을 가지므로 두 교점의 $y$좌표가 같습니다. 따라서 거리는 단순히 $x$좌표의 차이로 계산할 수 있다는 점이 핵심입니다. 항상 주어진 조건을 먼저 정리하면 계산이 간단해집니다.",
