    "problem": "밑이 $2$인 함수 $f(x)=\\log_{2}(x-a)+c$의 그래프가 $A(3,3)$, $B(5,4)$를 지난다. 원점 $O$에 대하여 $\\triangle OAB$의 넓이의 두 배와 $a+c$의 합을 구하시오.",
