    "explanation": "**[핵심 개념]**\n- 로그함수의 성질: $f(x) = \\log_b(x-a) + c$는 점 $(a, c)$를 중심으로 평행이동한 함수\n- 두 점을 지나는 함수: 주어진 두 점의 좌표를 함수식에 대입하여 미지수를 구함\n- 삼각형의 넓이: 좌표가 주어진 삼각형의 넓이는 $\\frac{1}{2}|x_1(y_2-y_3) + x_2(y_3-y_1) + x_3(y_1-y_2)|$ 공식 사용\n\n**[풀이]**\n\n**Step 1: 주어진 조건을 식으로 나타내기**\n\n함수 $f(x) = \\log_3(x-a) + c$가 점 $A(5,2)$와 $B(11,3)$을 지나므로:\n- $f(5) = 2$: $\\log_3(5-a) + c = 2$ ... (1)\n- $f(11) = 3$: $\\log_3(11-a) + c = 3$ ... (2)\n\n**Step 2: 연립방정식 풀이**\n\n식 (2) - 식 (1):\n$$\\log_3(11-a) - \\log_3(5-a) = 1$$\n\n$$\\log_3\\left(\\frac{11-a}{5-a}\\right) = 1$$\n\n$$\\frac{11-a}{5-a} = 3$$\n\n$$11-a = 3(5-a)$$\n\n$$11-a = 15-3a$$\n\n$$2a = 4$$\n\n$$a = 2$$\n\n**Step 3: $c$ 값 구하기**\n\n식 (1)에 $a=2$ 대입:\n$$\\log_3(5-2) + c = 2$$\n\n$$\\log_3(3) + c = 2$$\n\n$$1 + c = 2$$\n\n$$c = 1$$\n\n**Step 4: 삼각형 $OAB$의 넓이 구하기**\n\n원점 $O(0,0)$, $A(5,2)$, $B(11,3)$일 때:\n\n$$\\text{넓이} = \\frac{1}{2}|0(2-3) + 5(3-0) + 11(0-2)|$$\n\n$$= \\frac{1}{2}|0 + 15 - 22|$$\n\n$$= \\frac{1}{2}|-7|$$\n\n$$= \\frac{7}{2}$$\n\n**Step 5: 답 구하기**\n\n삼각형 넓이의 두 배: $2 \\times \\frac{7}{2} = 7$\n\n$a + c$의 합: $2 + 1 = 3$\n\n따라서 구하는 값: $7 + 3 = 10$\n\n**[정답 확인]**\n$a=2$, $c=1$일 때 두 점을 모두 만족하고, 삼각형 넓이의 두 배 7과 $a+c$ 값 3의 합이 10이므로 정답이 맞다.\n\n**[오답 분석]**\n- ① 5: 삼각형 넓이만 계산하거나 $a+c$만 계산한 경우\n- ③ 9: 계산 실수로 삼각형 넓이를 $\\frac{9}{2}$로 잘못 구한 경우\n- ④ 12: 절댓값 처리를 잘못하여 넓이를 8로 구한 경우\n- ⑤ -3: 부호를 잘못 처리한 경우\n\n**[핵심 포인트]**\n두 점을 지나는 로그함수의 미지수는 로그 성질을 이용해 나누기로 한 항씩 소거하는 것이 핵심이고, 삼각형 넓이 공식에서 절댓값을 반드시 취해야 한다.",
