    "answer": 4,
    "explanation": "**[핵심 개념]**\n\n지수방정식을 풀기 위한 치환 기법이 중요합니다. $a^{2x} = (a^x)^2$ 형태의 식에서 $a^x = t$로 놓으면 이차방정식으로 변환할 수 있습니다. 또한 지수함수는 일대일 대응이므로, $2^x = k$이면 $x = \\log_2 k$로 유일하게 결정됩니다.\n\n**[풀이]**\n\n$2^{2x} - 12 \\cdot 2^x + 32 = 0$을 풀기 위해 $2^x = t$로 치환합니다.\n\n$2^{2x} = (2^x)^2 = t^2$이므로:\n$$t^2 - 12t + 32 = 0$$\n\n이 이차방정식을 인수분해합니다:\n$$t^2 - 12t + 32 = (t-4)(t-8) = 0$$\n\n따라서 $t = 4$ 또는 $t = 8$\n\n**경우 1: $2^x = 4$일 때**\n$$2^x = 2^2 \\Rightarrow x = 2$$\n\n**경우 2: $2^x = 8$일 때**\n$$2^x = 2^3 \\Rightarrow x = 3$$\n\n모든 실근의 합은:\n$$2 + 3 = 5$$\n\n**[정답 확인]**\n\n$x=2$일 때: $2^4 - 12 \\cdot 2^2 + 32 = 16 - 48 + 32 = 0$ ✓\n$x=3$일 때: $2^6 - 12 \\cdot 2^3 + 32 = 64 - 96 + 32 = 0$ ✓\n\n**[오답 분석]**\n\n- ① 2: $2+3$이 아니라 한 근만 선택한 오류\n- ② 12: 이차방정식의 계수 $-12$를 답으로 착각\n- ③ 17: 계산 실수로 근을 잘못 구함\n- ④ 8: 한 근의 값인 $2^x=8$을 답으로 착각\n\n**[핵심 포인트]**\n\n지수방정식은 반드시 치환을 통해 이차방정식으로 변환하고, 각 근을 다시 지수식으로 복원하여 $x$값을 구해야 합니다. 근의 공식이나 계수와의 혼동을 피하세요.",
