    "answer": 4,
    "explanation": "**[핵심 개념]**\n지수방정식을 풀기 위해 치환을 이용합니다. $a^{2x} = (a^x)^2$ 형태의 식에서 $a^x = t$로 놓으면 이차방정식으로 변환할 수 있습니다. 이때 $t > 0$의 조건을 만족해야 하며, 구한 $t$ 값으로부터 $x$ 값을 역으로 구합니다.\n\n**[풀이]**\n\n**1단계: 치환을 이용한 이차방정식 변환**\n\n$3^x = t$로 놓으면 ($t > 0$), $3^{2x} = (3^x)^2 = t^2$\n\n주어진 방정식은:\n$$t^2 - 12t + 27 = 0$$\n\n**2단계: 이차방정식 풀기**\n\n인수분해를 하면:\n$$(t - 3)(t - 9) = 0$$\n\n따라서 $t = 3$ 또는 $t = 9$\n\n(검증: $3 + 9 = 12$, $3 \\times 9 = 27$ ✓)\n\n**3단계: 각 경우에 대해 $x$ 구하기**\n\n**경우 1:** $3^x = 3$\n$$x = 1$$\n\n**경우 2:** $3^x = 9 = 3^2$\n$$x = 2$$\n\n**4단계: 모든 실근의 합 계산**\n\n$$x_1 + x_2 = 1 + 2 = 3$$\n\n**[정답 확인]**\n$x = 1$과 $x = 2$를 원래 방정식에 대입하면 모두 $0$이 되므로, 모든 실근의 합은 $3$입니다.\n\n**[오답 분석]**\n- **5**: 치환 후 판별식이나 근과 계수의 관계를 잘못 적용한 경우\n- **0**: 근이 음수라고 잘못 생각한 경우\n- **8**: 근을 $1$과 $2$ 대신 다른 값으로 계산한 경우\n- **22**: 계산 과정에서 큰 오류를 범한 경우\n\n**[핵심 포인트]**\n지수방정식은 반드시 **치환**으로 이차방정식(또는 일차방정식)으로 변환해야 합니다. 근과 계수의 관계를 이용하면 $t_1 + t_2 = 12$이지만, 최종 답은 $x$의 합이므로 각각 $3^x = t$ 형태에서 $x$를 구해야 합니다.",
