    "explanation": "**[핵심 개념]**\n로그부등식을 풀기 위해서는 다음 성질을 이용합니다:\n- $\\log_a b \\ge c$ (단, $a > 1$)는 $b \\ge a^c$와 동치\n- 로그의 진수는 항상 양수여야 함 (정의역 조건)\n- 밑이 1보다 크면 로그함수는 증가함수\n\n**[풀이]**\n\n**1단계: 첫 번째 부등식 정리**\n\n$\\log_3(x-1) \\ge 1$\n\n밑이 3 > 1이므로:\n$$x - 1 \\ge 3^1$$\n$$x - 1 \\ge 3$$\n$$x \\ge 4$$\n\n또한 진수가 양수여야 하므로: $x - 1 > 0$ → $x > 1$\n\n따라서 $x \\ge 4$\n\n**2단계: 두 번째 부등식 정리**\n\n$\\log_3(11-x) \\ge 1$\n\n밑이 3 > 1이므로:\n$$11 - x \\ge 3^1$$\n$$11 - x \\ge 3$$\n$$-x \\ge -8$$\n$$x \\le 8$$\n\n또한 진수가 양수여야 하므로: $11 - x > 0$ → $x < 11$\n\n따라서 $x \\le 8$\n\n**3단계: 두 조건을 동시에 만족하는 범위**\n\n$x \\ge 4$ 그리고 $x \\le 8$을 동시에 만족:\n$$4 \\le x \\le 8$$\n\n**4단계: 정수 해 찾기**\n\n이 범위에서 정수 $x$는:\n$$x \\in \\{4, 5, 6, 7, 8\\}$$\n\n**5단계: 모든 가능한 $x$값의 합**\n\n$$4 + 5 + 6 + 7 + 8 = 30$$\n\n**[정답 확인]**\n$4 \\le x \\le 8$의 정수 해는 4, 5, 6, 7, 8이고, 이들의 합은 30입니다.\n\n**[오답 분석]**\n- **27**: $4 + 5 + 6 + 7 + 5 = 27$ (계산 오류)\n- **17**: $4 + 5 + 8 = 17$ (일부 정수만 더한 경우)\n- **28**: $4 + 5 + 6 + 7 + 6 = 28$ (숫자 중복 또는 계산 실수)\n- **25**: $4 + 5 + 6 + 7 = 22$ 또는 다른 계산 오류 (경계값 포함 실수)\n\n**[핵심 포인트]**\n1. 로그부등식의 진수 조건(양수)과 로그 계산 조건을 모두 확인해야 합니다.\n2. 연속된 정수의 합은 (첫 항 + 끝 항) × 항의 개수 ÷ 2로 빠르게 계산 가능합니다: $(4+8) \\times 5 \\div 2 = 30$",
