    "explanation": "**[핵심 개념]**\n로그의 정의와 성질을 이용하여 방정식을 풀어야 한다.\n- $\\log_a b = \\log_a c$ 이면 $b = c$ (단, $a > 0, a \\neq 1$, $b, c > 0$)\n- 로그의 진수는 항상 양수여야 한다는 정의역 조건 필수\n\n**[풀이]**\n\n**1단계: 로그 방정식을 지수 방정식으로 변환**\n\n$\\log_2((x-2)(8-x)) = \\log_2 5$\n\n로그의 정의에 의해:\n$$（x-2)(8-x) = 5$$\n\n**2단계: 정의역 확인**\n\n로그의 진수는 양수여야 하므로:\n$$(x-2)(8-x) > 0$$\n\n이는 $2 < x < 8$을 의미한다.\n\n**3단계: 방정식 풀이**\n\n$(x-2)(8-x) = 5$를 전개하면:\n$$8x - x^2 - 16 + 2x = 5$$\n$$-x^2 + 10x - 16 = 5$$\n$$-x^2 + 10x - 21 = 0$$\n$$x^2 - 10x + 21 = 0$$\n\n**4단계: 인수분해**\n\n$$x^2 - 10x + 21 = (x-3)(x-7) = 0$$\n\n따라서 $x = 3$ 또는 $x = 7$\n\n**5단계: 정의역 검증**\n\n- $x = 3$: $2 < 3 < 8$ ✓ 만족\n- $x = 7$: $2 < 7 < 8$ ✓ 만족\n\n두 근 모두 정의역을 만족한다.\n\n**6단계: 서로 다른 실근의 합**\n\n$$3 + 7 = 10$$\n\n**[정답 확인]**\n방정식을 정리하면 $x^2 - 10x + 21 = 0$이 되고, 두 근 $x=3, x=7$은 모두 정의역 조건 $2 < x < 8$을 만족하므로 그 합은 10이다.\n\n**[오답 분석]**\n- **②번 15**: 정의역을 확인하지 않고 근의 공식에서 계수만 사용한 경우 ($10$을 선택하지 못함)\n- **③번 33**: 계산 실수로 $x^2 - 10x + 21 = 0$을 잘못 풀어서 나온 오답\n- **④번 12**: 한 근만 계산하거나 다른 계산 오류\n- **⑤번 5**: 근과 계수의 관계를 잘못 적용한 경우\n\n**[핵심 포인트]**\n로그 방정식을 풀 때는 반드시 **진수의 양수 조건(정의역)**을 확인하여 구한 근이 실제로 유효한지 검증해야 한다. 이 문제에서 두 근 모두 정의역을 만족하므로 모두 해가 된다.",
