    "explanation": "**[핵심 개념]**\n\n로그의 성질을 이용한 방정식 풀이:\n- $\\log_a f(x) = \\log_a g(x)$ ⟹ $f(x) = g(x)$ (단, $f(x) > 0, g(x) > 0$)\n- 정의역: 로그의 진수는 반드시 양수여야 함\n- 이차방정식의 근과 계수의 관계: 근의 합 = $-\\frac{b}{a}$\n\n**[풀이]**\n\n**1단계: 로그 방정식을 지수 형태로 변환**\n\n$$\\log_{3}\\bigl((x-1)(7-x)\\bigr)=\\log_{3}5$$\n\n양변의 로그 밑이 같으므로:\n$$(x-1)(7-x) = 5$$\n\n**2단계: 정의역 확인**\n\n로그가 정의되려면 $(x-1)(7-x) > 0$이어야 합니다.\n\n$(x-1)(7-x) > 0$ ⟹ $1 < x < 7$\n\n**3단계: 이차방정식으로 정리**\n\n$$(x-1)(7-x) = 5$$\n$$7x - x^2 - 7 + x = 5$$\n$$-x^2 + 8x - 7 = 5$$\n$$-x^2 + 8x - 12 = 0$$\n$$x^2 - 8x + 12 = 0$$\n\n**4단계: 근의 공식 또는 인수분해**\n\n$$x^2 - 8x + 12 = 0$$\n$$(x-2)(x-6) = 0$$\n\n따라서 $x = 2$ 또는 $x = 6$\n\n**5단계: 정의역 검증**\n\n- $x = 2$: $1 < 2 < 7$ ✓ (유효)\n- $x = 6$: $1 < 6 < 7$ ✓ (유효)\n\n**6단계: 근의 합 계산**\n\n$$2 + 6 = 8$$\n\n또는 근과 계수의 관계에서: 근의 합 = $\\frac{8}{1} = 8$\n\n**[정답 확인]**\n\n두 근 $x=2, x=6$이 모두 정의역 $1 < x < 7$을 만족하므로 서로 다른 실근의 합은 $8$입니다.\n\n**[오답 분석]**\n\n- **10**: $(x-1)(7-x) = 10$으로 잘못 계산한 경우\n- **15**: 근과 계수의 관계를 잘못 적용하거나 계산 실수\n- **5**: 한 근만 계산한 경우 또는 정의역 검증 누락\n- **17**: 정의역을 고려하지 않고 다른 조건으로 계산한 경우\n\n**[핵심 포인트]**\n\n1. **정의역 확인 필수**: 로그 방정식은 반드시 진수가 양수인지 확인하여 불필요한 근을 제거해야 함\n2. **근과 계수의 관계**: 복잡한 계산 없이 $x^2 - 8x + 12 = 0$에서 근의 합 = $8$을 직접 구할 수 있음",
