    "explanation": "**[핵심 개념]**\n지수함수 $y=3^{x-1}$의 그래프 위의 점들을 구하는 방법과 세 점으로 만든 삼각형의 넓이를 구하는 공식이 필요합니다. 원점 $O(0,0)$과 두 점 $A, B$로 만든 삼각형의 넓이는 $\\frac{1}{2}|x_1y_2 - x_2y_1|$로 구할 수 있습니다.\n\n**[풀이]**\n\n**1단계: 점 A, B의 좌표 구하기**\n\n$x=1$일 때: $y=3^{1-1}=3^0=1$ → $A(1,1)$\n\n$x=3$일 때: $y=3^{3-1}=3^2=9$ → $B(3,9)$\n\n**2단계: 삼각형 OAB의 넓이 계산**\n\n원점 $O(0,0)$, $A(1,1)$, $B(3,9)$로 만든 삼각형의 넓이는:\n\n$$\\text{넓이} = \\frac{1}{2}|x_A \\cdot y_B - x_B \\cdot y_A|$$\n\n$$= \\frac{1}{2}|1 \\times 9 - 3 \\times 1|$$\n\n$$= \\frac{1}{2}|9 - 3|$$\n\n$$= \\frac{1}{2} \\times 6 = 3$$\n\n**3단계: 넓이의 두 배 구하기**\n\n$$2 \\times 3 = 6$$\n\n**[정답 확인]**\n점 A(1,1), B(3,9)로 만든 삼각형 OAB의 넓이가 3이므로, 그 두 배는 6입니다.\n\n**[오답 분석]**\n- **7**: 계산 실수로 넓이를 3.5로 잘못 구한 경우\n- **13**: 좌표값을 잘못 대입하거나 공식을 잘못 적용한 경우\n- **18**: 넓이 공식 $\\frac{1}{2}|x_1y_2 - x_2y_1|$에서 절댓값을 빼먹고 $|9-3|=6$의 두 배를 $6 \\times 3 = 18$로 계산한 경우\n- **29**: 지수함수 값을 잘못 계산하거나 여러 단계에서 오류를 범한 경우\n\n**[핵심 포인트]**\n원점을 포함한 삼각형의 넓이는 $\\frac{1}{2}|x_1y_2 - x_2y_1|$ 공식을 사용하면 간단하게 구할 수 있습니다. 지수함수의 함숫값을 정확하게 계산하는 것이 중요합니다.",
