    "answer": 3,
    "explanation": "**[핵심 개념]**\n지수함수 $f(x) = 2^{x-a} + c$는 두 점을 지나가는 조건으로부터 미지수 $a, c$를 결정할 수 있습니다. 주어진 두 점의 좌표를 함수식에 대입하면 $a$와 $c$에 대한 연립방정식을 얻을 수 있고, 이를 풀어 정수해를 찾으면 됩니다.\n\n**[풀이]**\n\n**Step 1: 주어진 점들을 함수식에 대입**\n\n함수 $f(x) = 2^{x-a} + c$가 점 $(2, 5)$를 지나므로:\n$$f(2) = 2^{2-a} + c = 5 \\cdots (1)$$\n\n함수가 점 $(4, 11)$을 지나므로:\n$$f(4) = 2^{4-a} + c = 11 \\cdots (2)$$\n\n**Step 2: 연립방정식 풀이**\n\n식 (2)에서 식 (1)을 빼면:\n$$2^{4-a} - 2^{2-a} = 6$$\n\n$2^{2-a}$로 인수분해하면:\n$$2^{2-a}(2^{2} - 1) = 6$$\n$$2^{2-a} \\cdot 3 = 6$$\n$$2^{2-a} = 2$$\n$$2^{2-a} = 2^1$$\n\n따라서:\n$$2 - a = 1$$\n$$a = 1$$\n\n**Step 3: $c$ 값 구하기**\n\n$a = 1$을 식 (1)에 대입:\n$$2^{2-1} + c = 5$$\n$$2^1 + c = 5$$\n$$2 + c = 5$$\n$$c = 3$$\n\n**Step 4: $f(5) + ac$ 계산**\n\n$$f(5) = 2^{5-1} + 3 = 2^4 + 3 = 16 + 3 = 19$$\n\n$$ac = 1 \\times 3 = 3$$\n\n$$f(5) + ac = 19 + 3 = 22$$\n\n**[정답 확인]**\n$a=1, c=3$일 때 $f(2) = 2 + 3 = 5$, $f(4) = 16 + 3 = 19$... (오류 확인: $f(4) = 2^{4-1} + 3 = 8 + 3 = 11$ ✓), 따라서 $f(5) + ac = 19 + 3 = 22$\n\n**[오답 분석]**\n- **20**: $f(5) = 19$를 구했지만 $ac$를 더하지 않은 경우\n- **21**: 계산 실수로 $f(5) = 18$로 잘못 구한 경우\n- **9**: $a, c$ 값을 잘못 구한 경우\n- **31**: $f(5)$와 $ac$를 더할 때 덧셈 실수를 한 경우\n\n**[핵심 포인트]**\n두 점을 지나는 조건에서 연립방정식을 세울 때, 지수함수의 차이를 이용하면 지수 항만 남겨 $a$를 쉽게 구할 수 있습니다. 구한 $a, c$가 정수인지 반드시 확인하세요.",
